  using (shop_id = (select app_shop_id()) and (select app_is_owner())) with check (shop_id = (select app_shop_id()) and (select app_is_owner()));

-- Cấu hình (nguyên liệu, menu, công thức, khu, bàn): nhân viên đọc, chủ ghi
