-- >>> 013_staff_birth_date.sql
-- Fore · 013_staff_birth_date.sql
-- Thêm ngày sinh hồ sơ nhân viên và đồng bộ khi họ nhận lời mời.
-- Chạy sau 012_owner_dashboard.sql; không cần reset dữ liệu.

alter table staff add column if not exists birth_date date;

create or replace function accept_invite(p_invite uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  r shop_invites;
  v_staff uuid;
  v_name text;
  v_birth_date date;
begin
  if v_uid is null then raise exception 'NOT_LOGGED_IN'; end if;
  r := _invite_for_me(p_invite);
  v_name := coalesce(nullif(btrim(auth.jwt() -> 'user_metadata' ->> 'full_name'), ''), r.full_name);
  begin
    v_birth_date := nullif(auth.jwt() -> 'user_metadata' ->> 'birth_date', '')::date;
  exception when invalid_datetime_format then
    raise exception 'BIRTH_DATE_INVALID';
  end;

  select id into v_staff from staff where shop_id = r.shop_id and auth_user_id = v_uid;
  if v_staff is null then
    insert into staff (shop_id, auth_user_id, full_name, birth_date, role)
    values (r.shop_id, v_uid, v_name, v_birth_date, 'staff')
    returning id into v_staff;
  else
    update staff
       set active = true, role = 'staff', full_name = v_name,
           birth_date = coalesce(v_birth_date, birth_date)
     where id = v_staff;
  end if;

  update shop_invites set status = 'accepted', responded_at = now(), accepted_user_id = v_uid where id = r.id;
  insert into user_settings (auth_user_id, active_shop_id) values (v_uid, r.shop_id)
    on conflict (auth_user_id) do update set active_shop_id = excluded.active_shop_id;
  insert into audit_log (shop_id, actor, action, entity, entity_id, detail)
    values (r.shop_id, v_staff, 'accept_invite', 'shop_invites', r.id, null);
  return v_staff;
end $$;

revoke all on function accept_invite(uuid) from public, anon;
grant execute on function accept_invite(uuid) to authenticated;


-- >>> 014_invite_phone_or_email.sql
-- Cho phép chủ mời nhân viên bằng điện thoại, email hoặc cả hai.
-- Chạy sau 013_staff_birth_date.sql.
alter table shop_invites alter column phone drop not null;
drop index if exists one_pending_invite;
create unique index if not exists one_pending_invite_phone
  on shop_invites (shop_id, phone) where status = 'pending' and phone is not null;
create unique index if not exists one_pending_invite_email
  on shop_invites (shop_id, email) where status = 'pending' and email is not null;

create or replace function invite_staff(p_phone text, p_full_name text, p_email text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := _require_owner();
  v_phone text := case when nullif(btrim(p_phone), '') is null then null else normalize_phone(p_phone) end;
  v_email text := nullif(lower(btrim(p_email)), '');
  v_id uuid;
begin
  -- Có nhập số mà không đọc được thì báo sai số, không được lặng lẽ bỏ qua rồi chỉ mời bằng email.
  if nullif(btrim(p_phone), '') is not null and (v_phone is null or v_phone !~ '^[1-9][0-9]{7,14}$') then
    raise exception 'PHONE_INVALID';
  end if;
  if v_phone is null and v_email is null then raise exception 'CONTACT_REQUIRED'; end if;
  if coalesce(btrim(p_full_name), '') = '' then raise exception 'NAME_REQUIRED'; end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'EMAIL_INVALID'; end if;
  if exists (
    select 1 from staff s join auth.users u on u.id = s.auth_user_id
    where s.shop_id = app_shop_id() and s.active and (
      (v_phone is not null and u.phone_confirmed_at is not null and normalize_phone(u.phone) = v_phone)
      or (v_email is not null and u.email_confirmed_at is not null and lower(u.email) = v_email)))
  then raise exception 'ALREADY_MEMBER'; end if;
  begin
    insert into shop_invites (shop_id, phone, email, full_name, invited_by)
    values (app_shop_id(), v_phone, v_email, btrim(p_full_name), v_me) returning id into v_id;
  exception when unique_violation then raise exception 'ALREADY_INVITED';
  end;
  perform _audit('invite_staff', 'shop_invites', v_id,
    jsonb_build_object('phone', v_phone, 'email', v_email, 'name', btrim(p_full_name)));
  return v_id;
end $$;
revoke all on function invite_staff(text, text, text) from public, anon;
grant execute on function invite_staff(text, text, text) to authenticated;


-- >>> 015_legacy_staff_contact_helpers.sql
-- Tương thích đọc danh sách tài khoản thử nghiệm cũ; không dùng email giả/metadata để xác thực,
-- đăng nhập hoặc khớp lời mời. Nhân viên cần dùng OTP với contact thật đã xác minh.
-- =====================================================================

-- Chỉ dùng để hiển thị số cũ trong team; không phải bằng chứng xác minh số điện thoại.
create or replace function _phone_login_domain() returns text
language sql immutable as $$ select 'phone.fore-staff.app'::text $$;

-- Email này có phải email giả đại diện cho số điện thoại không?
create or replace function _is_phone_login(p_email text) returns boolean
language sql immutable as $$
  select lower(btrim(coalesce(p_email, ''))) ~ ('^p[0-9]{8,15}@' || replace(_phone_login_domain(), '.', '\.') || '$')
$$;

-- Số điện thoại của một tài khoản (dạng 84901234567): số đã xác thực của Supabase,
-- hoặc số nằm trong email giả. `null` nếu tài khoản không có số.
create or replace function _auth_phone(p_phone text, p_phone_confirmed_at timestamptz, p_email text) returns text
language sql immutable as $$
  select coalesce(
    case when p_phone_confirmed_at is not null then normalize_phone(p_phone) end,
    case when _is_phone_login(p_email)
         then substring(lower(btrim(p_email)) from '^p([0-9]+)@') end)
$$;

-- Email thật của một tài khoản (đã xác nhận, không tính email giả). `null` nếu không có.
create or replace function _auth_email(p_email text, p_email_confirmed_at timestamptz) returns text
language sql immutable as $$
  select case when p_email_confirmed_at is not null and not _is_phone_login(p_email)
              then lower(btrim(p_email)) end
$$;

revoke all on function _phone_login_domain(), _is_phone_login(text), _auth_phone(text, timestamptz, text),
  _auth_email(text, timestamptz) from public, anon, authenticated;

-- Liên hệ của người đang đăng nhập, dùng để tìm lời mời gửi cho họ.
create or replace function _my_verified_contacts(out phone text, out email text)
language plpgsql stable security definer set search_path = public as $$
begin
  select _auth_phone(u.phone, u.phone_confirmed_at, u.email),
         _auth_email(u.email, u.email_confirmed_at)
    into phone, email
    from auth.users u where u.id = auth.uid();
end $$;

-- Mời nhân viên: nhận ra người đã là thành viên dù họ đăng ký bằng số điện thoại, email thật hay email giả.
create or replace function invite_staff(p_phone text, p_full_name text, p_email text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := _require_owner();
  v_phone text := case when nullif(btrim(p_phone), '') is null then null else normalize_phone(p_phone) end;
  v_email text := nullif(lower(btrim(p_email)), '');
  v_id uuid;
begin
  -- Có nhập số mà không đọc được thì báo sai số, không được lặng lẽ bỏ qua rồi chỉ mời bằng email.
  if nullif(btrim(p_phone), '') is not null and (v_phone is null or v_phone !~ '^[1-9][0-9]{7,14}$') then
    raise exception 'PHONE_INVALID';
  end if;
  if v_phone is null and v_email is null then raise exception 'CONTACT_REQUIRED'; end if;
  if coalesce(btrim(p_full_name), '') = '' then raise exception 'NAME_REQUIRED'; end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'EMAIL_INVALID'; end if;
  if exists (
    select 1 from staff s join auth.users u on u.id = s.auth_user_id
    where s.shop_id = app_shop_id() and s.active and (
      (v_phone is not null and _auth_phone(u.phone, u.phone_confirmed_at, u.email) = v_phone)
      or (v_email is not null and _auth_email(u.email, u.email_confirmed_at) = v_email)))
  then raise exception 'ALREADY_MEMBER'; end if;
  begin
    insert into shop_invites (shop_id, phone, email, full_name, invited_by)
    values (app_shop_id(), v_phone, v_email, btrim(p_full_name), v_me) returning id into v_id;
  exception when unique_violation then raise exception 'ALREADY_INVITED';
  end;
  perform _audit('invite_staff', 'shop_invites', v_id,
    jsonb_build_object('phone', v_phone, 'email', v_email, 'name', btrim(p_full_name)));
  return v_id;
end $$;

-- Danh sách nhân viên cho chủ: số điện thoại lấy từ email giả, không hiện email giả ra màn hình.
create or replace function shop_team()
returns table (staff_id uuid, full_name text, role text, active boolean, phone text, email text, has_pin boolean, joined_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_owner();
  return query
    select s.id, s.full_name, s.role, s.active,
           _auth_phone(u.phone, u.phone_confirmed_at, u.email),
           case when _is_phone_login(u.email) then null else u.email::text end,
           s.pin_hash is not null, s.created_at
      from staff s left join auth.users u on u.id = s.auth_user_id
     where s.shop_id = app_shop_id()
     order by (s.role = 'owner') desc, s.active desc, s.created_at;
end $$;

revoke all on function invite_staff(text, text, text), shop_team() from public, anon;
grant execute on function invite_staff(text, text, text), shop_team() to authenticated;


-- >>> 016_audit_actor_same_shop.sql
-- Fore · 016_audit_actor_same_shop.sql · Sửa nhật ký khi một người thuộc NHIỀU quán
-- Chạy sau 015_simple_staff_login.sql; không cần reset dữ liệu.
--
-- LỖI: `audit_log_actor_same_shop_fk` (001) bắt buộc (shop_id, actor) phải cùng một quán. Trigger
-- `audit_row_change` lấy shop_id từ DÒNG bị đổi nhưng actor từ `app_staff_id()` (nhân viên ở quán ĐANG CHỌN).
-- Nên người đã ở quán A mà tạo quán B (`create_shop`) hoặc chấp nhận lời mời vào quán B (`accept_invite`)
-- sẽ ghi (shop B, nhân viên của A) và bị khóa ngoại chặn: thao tác thất bại.
--
-- SỬA: actor là nhân viên của CHÍNH QUÁN CỦA DÒNG đó (nếu người này chưa là nhân viên ở đó thì để trống,
-- ví dụ lúc hệ thống tự gieo cấu hình cho quán vừa tạo).
create or replace function audit_row_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_old jsonb; v_new jsonb; v_shop uuid; v_actor uuid;
begin
  if tg_op in ('UPDATE','DELETE') then v_old := to_jsonb(old) - 'pin_hash'; end if;
  if tg_op in ('INSERT','UPDATE') then v_new := to_jsonb(new) - 'pin_hash'; end if;
  v_shop := coalesce((v_new->>'shop_id')::uuid, (v_old->>'shop_id')::uuid, app_shop_id());
  select s.id into v_actor from staff s
   where s.auth_user_id = auth.uid() and s.shop_id = v_shop and s.active;
  insert into audit_log (shop_id, actor, action, entity, entity_id, detail)
  values (v_shop, v_actor, lower(tg_op), tg_table_name,
          coalesce(v_new->>'id', v_old->>'id')::uuid,
          jsonb_build_object('old', v_old, 'new', v_new));
  return coalesce(new, old);
end $$;


-- >>> 017_staff_invite_contact_fallback.sql
-- Fore · 017_legacy_staff_contact_display.sql
-- Legacy helper giữ lại để hiển thị team cũ; không xác minh hoặc nhận lời mời bằng alias.
-- Chạy sau 015_simple_staff_login.sql và 016_audit_actor_same_shop.sql.
-- Không thay đổi dữ liệu hiện có; lời mời pending sẽ khớp ngay sau khi chạy.
-- TEST ONLY: không dùng cơ chế đăng nhập không xác minh này cho môi trường production.

-- Giữ migration tự chứa để dùng được cả với bộ cài hợp nhất.
create or replace function _is_demo_staff_phone_email(p_email text)
returns boolean
language sql immutable as $$
  select lower(btrim(coalesce(p_email, ''))) ~ '^p[0-9]{8,15}@phone[.]fore-staff[.]app$'
$$;

create or replace function _demo_staff_phone(
  p_phone text,
  p_phone_confirmed_at timestamptz,
  p_email text,
  p_metadata jsonb
) returns text
language sql immutable as $$
  select coalesce(
    normalize_phone(p_metadata ->> 'demo_phone'),
    case when p_phone_confirmed_at is not null then normalize_phone(p_phone) end,
    case when _is_demo_staff_phone_email(p_email)
      then substring(lower(btrim(p_email)) from '^p([0-9]+)@') end
  )
$$;

create or replace function _demo_staff_email(
  p_email text,
  p_email_confirmed_at timestamptz,
  p_metadata jsonb
) returns text
language sql immutable as $$
  select coalesce(
    nullif(lower(btrim(p_metadata ->> 'demo_email')), ''),
    case when p_email_confirmed_at is not null
           and not _is_demo_staff_phone_email(p_email)
      then lower(btrim(p_email)) end,
    case when p_email is not null and not _is_demo_staff_phone_email(p_email)
      then lower(btrim(p_email)) end
  )
$$;
revoke all on function _is_demo_staff_phone_email(text),
  _demo_staff_phone(text, timestamptz, text, jsonb),
  _demo_staff_email(text, timestamptz, jsonb)
  from public, anon, authenticated;

create or replace function _my_verified_contacts(out phone text, out email text)
language plpgsql stable security definer set search_path = public, auth as $$
declare
  v_meta jsonb;
  v_raw_phone text;
  v_phone_confirmed_at timestamptz;
  v_raw_email text;
  v_email_confirmed_at timestamptz;
begin
  select u.raw_user_meta_data, u.phone::text, u.phone_confirmed_at,
         u.email::text, u.email_confirmed_at
    into v_meta, v_raw_phone, v_phone_confirmed_at,
         v_raw_email, v_email_confirmed_at
    from auth.users u
   where u.id = auth.uid();

  -- Metadata do app mới ghi được; các tài khoản cũ fallback về danh tính Auth.
  -- _auth_phone nhận diện email giả p<phone>@phone.fore-staff.app.
  phone := _demo_staff_phone(
    v_raw_phone, v_phone_confirmed_at, v_raw_email, v_meta);
  email := _demo_staff_email(v_raw_email, v_email_confirmed_at, v_meta);
end $$;
revoke all on function _my_verified_contacts() from public, anon, authenticated;

-- Chỉ contact Auth đã xác minh mới ngăn chủ gửi lời mời trùng cho thành viên hiện có.
create or replace function invite_staff(
  p_phone text,
  p_full_name text,
  p_email text default null
) returns uuid
language plpgsql security definer set search_path = public, auth as $$
declare
  v_me uuid := _require_owner();
  v_phone text := case
    when nullif(btrim(p_phone), '') is null then null
    else normalize_phone(p_phone)
  end;
  v_email text := nullif(lower(btrim(p_email)), '');
  v_id uuid;
begin
  -- Nếu chủ đã nhập số nhưng số không hợp lệ, không âm thầm bỏ số rồi mời bằng email.
  if nullif(btrim(p_phone), '') is not null
     and (v_phone is null or v_phone !~ '^[1-9][0-9]{7,14}$') then
    raise exception 'PHONE_INVALID';
  end if;
  if v_phone is null and v_email is null then
    raise exception 'CONTACT_REQUIRED';
  end if;
  if coalesce(btrim(p_full_name), '') = '' then
    raise exception 'NAME_REQUIRED';
  end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'EMAIL_INVALID';
  end if;

  if exists (
    select 1
      from staff s
      join auth.users u on u.id = s.auth_user_id
     where s.shop_id = app_shop_id()
       and s.active
       and (
         (v_phone is not null and u.phone_confirmed_at is not null
           and normalize_phone(u.phone::text) = v_phone)
         or
         (v_email is not null and u.email_confirmed_at is not null
           and not _is_phone_login(u.email::text)
           and lower(btrim(u.email::text)) = v_email)
       )
  ) then
    raise exception 'ALREADY_MEMBER';
  end if;

  begin
    insert into shop_invites(shop_id, phone, email, full_name, invited_by)
    values (app_shop_id(), v_phone, v_email, btrim(p_full_name), v_me)
    returning id into v_id;
  exception when unique_violation then
    raise exception 'ALREADY_INVITED';
  end;

  perform _audit('invite_staff', 'shop_invites', v_id,
    jsonb_build_object('phone', v_phone, 'email', v_email, 'name', btrim(p_full_name)));
  return v_id;
end $$;
revoke all on function invite_staff(text, text, text) from public, anon;
grant execute on function invite_staff(text, text, text) to authenticated;


-- >>> 018_session_context.sql
-- Fore · 018_session_context.sql
-- Trạng thái phiên do máy chủ quyết định. account_kind chỉ chọn luồng khởi tạo;
-- quyền truy cập luôn lấy từ membership staff đang hoạt động trong từng quán.

create or replace function my_session_context(p_preferred_shop uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_active_shop uuid;
  v_account_kind text;
  v_shops jsonb;
  v_pending_invites integer := 0;
begin
  if v_uid is null then raise exception 'NOT_LOGGED_IN'; end if;
  if not validate_staff_device() then raise exception 'STAFF_DEVICE_UNTRUSTED'; end if;

  -- Client có thể gửi lần chọn gần nhất, nhưng chỉ membership đang hoạt động mới được dùng.
  if p_preferred_shop is not null and exists (
    select 1 from staff s
     where s.auth_user_id = v_uid and s.shop_id = p_preferred_shop and s.active
  ) then
    insert into user_settings (auth_user_id, active_shop_id)
    values (v_uid, p_preferred_shop)
    on conflict (auth_user_id) do update set active_shop_id = excluded.active_shop_id;
  end if;

  -- app_metadata do _stamp_account_kind đóng dấu; user_metadata người dùng sửa được nên không tin.
  select case when u.raw_app_meta_data->>'fore_account_kind' in ('owner', 'staff')
              then u.raw_app_meta_data->>'fore_account_kind'
              else 'unknown' end
    into v_account_kind
    from auth.users u where u.id = v_uid;
  v_account_kind := coalesce(v_account_kind, 'unknown');
  v_active_shop := app_shop_id();

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'shop_id', s.shop_id,
      'shop_name', sh.name,
      'staff_id', s.id,
      'full_name', s.full_name,
      'role', s.role,
      'active', s.active,
      'has_pin', s.pin_hash is not null,
      'is_current', s.shop_id = v_active_shop
    ) order by s.created_at, s.id
  ), '[]'::jsonb)
    into v_shops
    from staff s join shops sh on sh.id = s.shop_id
   where s.auth_user_id = v_uid and s.active;

  select count(*)::integer into v_pending_invites from my_invites();

  return jsonb_build_object(
    'account_kind', v_account_kind,
    'shops', v_shops,
    'active_shop_id', v_active_shop,
    'pending_invite_count', v_pending_invites
  );
end;
$$;

revoke all on function my_session_context(uuid) from public, anon;
grant execute on function my_session_context(uuid) to authenticated;


-- >>> 019_invite_expiry.sql
-- Fore · 019_invite_expiry.sql
-- Lời mời chờ quá 14 ngày được đóng thành expired khi người nhận hoặc chủ tải lại.
-- Dữ liệu chỉ đổi trạng thái; không xóa lời mời hay membership.

alter table shop_invites drop constraint if exists shop_invites_status_check;
alter table shop_invites add constraint shop_invites_status_check
  check (status in ('pending', 'accepted', 'declined', 'cancelled', 'expired'));

create or replace function expire_my_invites() returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_phone text;
  v_email text;
  v_count integer;
begin
  if auth.uid() is null then raise exception 'NOT_LOGGED_IN'; end if;
  select c.phone, c.email into v_phone, v_email from _my_verified_contacts() c;

  update shop_invites i
     set status = 'expired', responded_at = now()
   where i.status = 'pending'
     and i.created_at <= now() - interval '14 days'
     and (
       (v_phone is not null and i.phone = v_phone)
       or (v_email is not null and i.email = v_email)
       or (i.shop_id = app_shop_id() and app_is_owner())
     );
  get diagnostics v_count = row_count;
  return v_count;
end $$;

-- Đọc lại hộp thư cũng phải áp dụng thời hạn trước khi trả lời lời mời.
-- Hàm này phải VOLATILE vì cập nhật status qua expire_my_invites().
create or replace function my_invites()
returns table (invite_id uuid, shop_id uuid, shop_name text, invited_name text,
               invited_by_name text, created_at timestamptz)
language plpgsql volatile security definer set search_path = public as $$
declare
  v_phone text;
  v_email text;
begin
  if auth.uid() is null then raise exception 'NOT_LOGGED_IN'; end if;
  perform expire_my_invites();
  select c.phone, c.email into v_phone, v_email from _my_verified_contacts() c;
  return query
    select i.id, i.shop_id, sh.name, i.full_name, inv.full_name, i.created_at
      from shop_invites i
      join shops sh on sh.id = i.shop_id
      join staff inv on inv.id = i.invited_by
     where i.status = 'pending'
       and ((v_phone is not null and i.phone = v_phone)
         or (v_email is not null and i.email = v_email))
     order by i.created_at desc;
end $$;

create or replace function _invite_for_me(p_invite uuid) returns shop_invites
language plpgsql security definer set search_path = public as $$
declare
  v_phone text;
  v_email text;
  r shop_invites;
begin
  if auth.uid() is null then raise exception 'NOT_LOGGED_IN'; end if;
  select c.phone, c.email into v_phone, v_email from _my_verified_contacts() c;
  select * into r from shop_invites i
   where i.id = p_invite and i.status = 'pending'
     and ((v_phone is not null and i.phone = v_phone)
       or (v_email is not null and i.email = v_email))
   for update;
  if found then return r; end if;

  if exists (
    select 1 from shop_invites i
     where i.id = p_invite and i.status = 'expired'
       and ((v_phone is not null and i.phone = v_phone)
         or (v_email is not null and i.email = v_email))
  ) then
    raise exception 'INVITE_EXPIRED';
  end if;
  raise exception 'INVITE_NOT_FOUND';
end $$;

revoke all on function expire_my_invites() from public, anon;
grant execute on function expire_my_invites() to authenticated;
revoke all on function my_invites() from public, anon;
grant execute on function my_invites() to authenticated;
revoke all on function _invite_for_me(uuid) from public, anon, authenticated;


-- >>> 020_owner_sales_trend.sql
-- Fore · 020_owner_sales_trend.sql
-- Bảy ngày kinh doanh, tính từ 06:00 theo thời gian truyền từ app.
-- Ngày hiện tại chỉ tính đến giờ hiện tại; chỉ chủ quán mới đọc được chuỗi này.

create or replace function owner_sales_trend(
  p_business_start timestamptz,
  p_days integer default 7
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_shop uuid := app_shop_id();
  v_trend jsonb;
begin
  if v_shop is null or not app_is_owner() then
    raise exception 'OWNER_ONLY';
  end if;
  if p_business_start is null
     or p_business_start > now()
     or p_business_start < now() - interval '36 hours'
     or p_days is null or p_days < 1 or p_days > 14 then
    raise exception 'DATE_RANGE_INVALID';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'business_start', d.business_start,
      'sales', coalesce(s.total, 0)::bigint
    ) order by d.business_start
  ), '[]'::jsonb)
    into v_trend
    from generate_series(p_days - 1, 0, -1) as offsets(day_offset)
    cross join lateral (
      select p_business_start - day_offset * interval '1 day' as business_start
    ) d
    cross join lateral (
      select sum(b.total_amount)::bigint as total
        from bills b
       where b.shop_id = v_shop
         and b.status = 'paid'
         and b.paid_at >= d.business_start
         and b.paid_at < least(d.business_start + interval '1 day', now())
    ) s;

  return v_trend;
end $$;

revoke all on function owner_sales_trend(timestamptz, integer) from public, anon;
grant execute on function owner_sales_trend(timestamptz, integer) to authenticated;


-- >>> 021_staff_otp_device_trust.sql
-- Nhân viên phải xác minh OTP trên từng thiết bị. Mỗi Auth session có một proof 60 ngày;
-- Flutter chỉ giữ proof trong secure storage, database chỉ giữ SHA-256 digest.
create table if not exists staff_trusted_devices (
  user_id uuid not null references auth.users(id) on delete cascade,
  session_id uuid not null,
  secret_hash bytea not null check (octet_length(secret_hash) = 32),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  primary key (user_id, session_id)
);
alter table staff_trusted_devices enable row level security;
revoke all on staff_trusted_devices from public, anon, authenticated;

-- user_metadata do chính người dùng sửa được (auth.updateUser), app_metadata thì không.
-- Chép account_kind sang app_metadata ngay lúc tạo tài khoản và chỉ tin bản chép đó,
-- để không ai tự gỡ nhãn "staff" nhằm né kiểm tra thiết bị.
create or replace function _stamp_account_kind() returns trigger
language plpgsql security definer set search_path = public, auth as $$
begin
  if not (coalesce(new.raw_app_meta_data, '{}'::jsonb) ? 'fore_account_kind') then
    new.raw_app_meta_data := coalesce(new.raw_app_meta_data, '{}'::jsonb)
      || jsonb_build_object('fore_account_kind', new.raw_user_meta_data->>'account_kind');
  end if;
  return new;
end $$;

drop trigger if exists stamp_account_kind on auth.users;
create trigger stamp_account_kind before insert on auth.users
  for each row execute function _stamp_account_kind();

-- Tài khoản có sẵn: lấy theo metadata hiện tại (đã có thể bị sửa, nên rà lại nếu nghi ngờ).
update auth.users
   set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb)
     || jsonb_build_object('fore_account_kind', raw_user_meta_data->>'account_kind')
 where not (coalesce(raw_app_meta_data, '{}'::jsonb) ? 'fore_account_kind');

-- Tài khoản mới chưa có hàng staff nên account_kind chỉ nhận dạng luồng đăng ký;
-- khi có membership, role trong bảng staff vẫn là nguồn phân quyền quyết định.
create or replace function _auth_user_is_staff(p_user uuid) returns boolean
language sql stable security definer set search_path = public, auth as $$
  select exists (
    select 1 from staff s where s.auth_user_id = p_user and s.active and s.role = 'staff'
  ) or exists (
    select 1 from auth.users u
     where u.id = p_user and u.raw_app_meta_data->>'fore_account_kind' = 'staff'
  )
$$;

create or replace function staff_device_is_trusted() returns boolean
language sql stable security definer set search_path = public, auth, extensions as $$
  select case
    when auth.uid() is null then false
    when not _auth_user_is_staff(auth.uid()) then true
    else exists (
      select 1
        from staff_trusted_devices d
       where d.user_id = auth.uid()
         and d.session_id = nullif(auth.jwt()->>'session_id', '')::uuid
         and d.secret_hash = extensions.digest(
           coalesce(nullif(current_setting('request.headers', true), '')::jsonb
             ->> 'x-fore-device-token', ''), 'sha256')
         and d.expires_at > now()
    )
  end
$$;

create or replace function validate_staff_device() returns boolean
language sql stable security definer set search_path = public, auth as $$
  select staff_device_is_trusted()
$$;

create or replace function register_staff_device(p_secret text) returns timestamptz
language plpgsql security definer set search_path = public, auth, extensions as $$
declare
  v_uid uuid := auth.uid();
  v_session uuid;
  v_expires timestamptz := now() + interval '60 days';
begin
  if v_uid is null then raise exception 'NOT_LOGGED_IN'; end if;
  if not _auth_user_is_staff(v_uid) then raise exception 'NOT_STAFF'; end if;
  if p_secret is null or p_secret !~ '^[A-Za-z0-9_-]{40,100}$' then
    raise exception 'DEVICE_TOKEN_INVALID';
  end if;
  if not exists (
    select 1 from jsonb_array_elements(coalesce(auth.jwt()->'amr', '[]'::jsonb)) method
     where method->>'method' in ('otp', 'signup')
  ) then raise exception 'OTP_REQUIRED'; end if;
  begin
    v_session := nullif(auth.jwt()->>'session_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'SESSION_INVALID';
  end;
  if v_session is null then raise exception 'SESSION_INVALID'; end if;

  insert into staff_trusted_devices (user_id, session_id, secret_hash, expires_at)
  values (v_uid, v_session, extensions.digest(p_secret, 'sha256'), v_expires)
  on conflict (user_id, session_id) do update
    set secret_hash = excluded.secret_hash,
        created_at = now(),
        expires_at = excluded.expires_at;
  return v_expires;
end $$;

-- Chỉ email/số đã được Supabase Auth xác nhận mới được dùng để nhận lời mời.
create or replace function _my_verified_contacts(out phone text, out email text)
language plpgsql stable security definer set search_path = public, auth as $$
begin
  if auth.uid() is null then raise exception 'NOT_LOGGED_IN'; end if;
  if not staff_device_is_trusted() then raise exception 'STAFF_DEVICE_UNTRUSTED'; end if;
  select case when u.phone_confirmed_at is not null then normalize_phone(u.phone) end,
         case when u.email_confirmed_at is not null then lower(btrim(u.email)) end
    into phone, email
    from auth.users u
   where u.id = auth.uid();
end $$;

-- RLS and all RPCs that use _require_staff resolve this replacement dynamically.
create or replace function app_staff_id() returns uuid
language sql stable security definer set search_path = public as $$
  select s.id
    from staff s
   where s.auth_user_id = auth.uid()
     and s.active
     and s.shop_id = app_shop_id()
     and (s.role = 'owner' or staff_device_is_trusted())
$$;

revoke all on function _auth_user_is_staff(uuid), staff_device_is_trusted() from public, anon, authenticated;
revoke all on function validate_staff_device(), register_staff_device(text) from public, anon;
grant execute on function validate_staff_device(), register_staff_device(text) to authenticated;


-- >>> SOURCE: database/05_menu_management.sql
-- Fore · 05_menu_management.sql · Quản lý THỰC ĐƠN của chủ quán
-- Áp dụng SAU 04_membership_sessions.sql. Chạy lại nhiều lần an toàn (create if not exists / or replace).
--
-- Mô hình: MỖI QUÁN một thực đơn riêng (menu_items/menu_sizes/ingredients đều có shop_id).
--   · Giá vốn = Σ (định lượng × ingredients.unit_cost). Thiếu giá một nguyên liệu thì "chưa xác định".
--   · Công thức theo PHIÊN BẢN: recipe_versions (+ recipe_version_lines). Bảng recipe_lines vẫn là công thức
--     ĐANG DÙNG (pay_bill ghi sổ kho theo nó). Phiên bản hẹn giờ được kích hoạt "lười" (_menu_apply_due) ở
--     những hàm bán hàng và hàm thực đơn, nên không cần cron. Sổ kho đã ghi lúc bán nên ca cũ không bị lệch.
--   · Đổi giá: price_changes (áp dụng ngay hoặc hẹn giờ). bill_lines.unit_price giữ giá lúc bán.
--   · Mọi thay đổi ghi vào menu_events để hiện "Lịch sử thay đổi".
--   · Định lượng là SỐ NGUYÊN theo đơn vị gốc (g, ml, cái) như sổ kho; chưa hỗ trợ số lẻ.

-- ---------- 1) Cột và bảng mới ----------
alter table ingredients add column if not exists unit_cost numeric(12,2) check (unit_cost is null or unit_cost >= 0);
alter table ingredients add column if not exists unit_cost_updated_at timestamptz;
alter table menu_items  add column if not exists is_draft boolean not null default false;
alter table menu_items  add column if not exists image_path text;
alter table menu_items  add column if not exists description text;

create table if not exists menu_categories (
  id         uuid primary key default gen_random_uuid(),
  shop_id    uuid not null default app_shop_id() references shops(id),
  name       text not null check (char_length(btrim(name)) >= 1),
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);
create unique index if not exists menu_categories_name_uq on menu_categories (shop_id, lower(btrim(name)));

create table if not exists recipe_versions (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid not null default app_shop_id() references shops(id),
  size_id        uuid not null references menu_sizes(id),
  version_no     integer not null check (version_no >= 1),
  status         text not null check (status in ('scheduled','active','superseded','cancelled')),
  effective_from timestamptz not null,
  applied_at     timestamptz,
  note           text,
  created_by     uuid references staff(id),
  created_at     timestamptz not null default now(),
  unique (size_id, version_no)
);
create index if not exists recipe_versions_due_idx on recipe_versions (shop_id, effective_from) where status = 'scheduled';

create table if not exists recipe_version_lines (
  version_id    uuid not null references recipe_versions(id) on delete cascade,
  ingredient_id uuid not null references ingredients(id),
  qty           integer not null check (qty > 0),
  primary key (version_id, ingredient_id)
);

create table if not exists price_changes (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid not null default app_shop_id() references shops(id),
  size_id        uuid not null references menu_sizes(id),
  old_price      integer not null check (old_price >= 0),
  new_price      integer not null check (new_price > 0),
  status         text not null check (status in ('scheduled','applied','cancelled')),
  effective_from timestamptz not null,
  applied_at     timestamptz,
  created_by     uuid references staff(id),
  created_at     timestamptz not null default now()
);
create index if not exists price_changes_due_idx on price_changes (shop_id, effective_from) where status = 'scheduled';

create table if not exists menu_events (
  id         uuid primary key default gen_random_uuid(),
  shop_id    uuid not null default app_shop_id() references shops(id),
  item_id    uuid references menu_items(id) on delete cascade,
  size_id    uuid references menu_sizes(id) on delete set null,
  kind       text not null,           -- created | recipe | price | status | category | copy | image | update
  summary    text not null,
  detail     jsonb,
  actor      uuid references staff(id),
  created_at timestamptz not null default now()
);
create index if not exists menu_events_item_idx on menu_events (item_id, created_at desc);

alter table menu_categories      enable row level security;
alter table recipe_versions      enable row level security;
alter table recipe_version_lines enable row level security;
alter table price_changes        enable row level security;
alter table menu_events          enable row level security;
-- Chỉ chủ đọc được; GHI chỉ qua các hàm bên dưới (security definer)
grant select on menu_categories, recipe_versions, recipe_version_lines, price_changes, menu_events to authenticated;
drop policy if exists menu_categories_read on menu_categories;
create policy menu_categories_read on menu_categories for select to authenticated
  using (shop_id = (select app_shop_id()) and (select app_staff_id()) is not null);
drop policy if exists recipe_versions_read on recipe_versions;
create policy recipe_versions_read on recipe_versions for select to authenticated
  using (shop_id = (select app_shop_id()) and (select app_is_owner()));
drop policy if exists recipe_version_lines_read on recipe_version_lines;
create policy recipe_version_lines_read on recipe_version_lines for select to authenticated
  using (exists (select 1 from recipe_versions v where v.id = version_id and v.shop_id = (select app_shop_id()) and (select app_is_owner())));
drop policy if exists price_changes_read on price_changes;
create policy price_changes_read on price_changes for select to authenticated
  using (shop_id = (select app_shop_id()) and (select app_is_owner()));
drop policy if exists menu_events_read on menu_events;
create policy menu_events_read on menu_events for select to authenticated
  using (shop_id = (select app_shop_id()) and (select app_is_owner()));

-- ---------- 2) Dữ liệu cũ: danh mục từ group_name, công thức hiện tại thành phiên bản 1 ----------
insert into menu_categories (shop_id, name, sort_order)
select shop_id, name, (row_number() over (partition by shop_id order by name))::integer
  from (select distinct shop_id, btrim(group_name) as name from menu_items
         where group_name is not null and btrim(group_name) <> '') g
 where not exists (select 1 from menu_categories c
                    where c.shop_id = g.shop_id and lower(btrim(c.name)) = lower(g.name))
on conflict do nothing;

with todo as (
  select ms.id as size_id, ms.shop_id
    from menu_sizes ms
   where exists (select 1 from recipe_lines rl where rl.size_id = ms.id)
     and not exists (select 1 from recipe_versions rv where rv.size_id = ms.id)
), ins as (
  insert into recipe_versions (shop_id, size_id, version_no, status, effective_from, applied_at)
  select shop_id, size_id, 1, 'active', timestamptz '1970-01-01', now() from todo
  returning id, size_id
)
insert into recipe_version_lines (version_id, ingredient_id, qty)
select ins.id, rl.ingredient_id, rl.qty from ins join recipe_lines rl on rl.size_id = ins.size_id;

-- ---------- 3) Hàm nội bộ ----------
create or replace function _menu_event(p_item uuid, p_size uuid, p_kind text, p_summary text, p_detail jsonb default null)
returns void language sql security definer set search_path = public as $$
  insert into menu_events (shop_id, item_id, size_id, kind, summary, detail, actor)
  values (app_shop_id(), p_item, p_size, p_kind, p_summary, p_detail, app_staff_id())
$$;

-- Công thức có hiệu lực tại một thời điểm (dùng cho đối soát: ca cũ vẫn tính theo công thức cũ)
create or replace function _recipe_at(p_size uuid, p_at timestamptz)
returns table (ingredient_id uuid, qty integer)
language sql stable security definer set search_path = public as $$
  select l.ingredient_id, l.qty
    from recipe_version_lines l
   where l.version_id = (select v.id from recipe_versions v
                          where v.size_id = p_size and v.status in ('active','superseded')
                            and v.effective_from <= p_at
                          order by v.version_no desc limit 1)
  union all
  select rl.ingredient_id, rl.qty
    from recipe_lines rl
   where rl.size_id = p_size
     and not exists (select 1 from recipe_versions v where v.size_id = p_size and v.status in ('active','superseded'))
$$;

create or replace function _recipe_activate(p_version uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v recipe_versions%rowtype;
begin
  select * into v from recipe_versions where id = p_version for update;
  if not found or v.status <> 'scheduled' then return; end if;
  perform set_config('fore.recipe_apply', 'on', true);
  delete from recipe_lines where size_id = v.size_id;
  insert into recipe_lines (shop_id, size_id, ingredient_id, qty)
  select v.shop_id, v.size_id, l.ingredient_id, l.qty from recipe_version_lines l where l.version_id = v.id;
  perform set_config('fore.recipe_apply', 'off', true);
  update recipe_versions set status = 'superseded' where size_id = v.size_id and status = 'active';
  update recipe_versions set status = 'active', applied_at = now() where id = v.id;
end $$;

-- Áp dụng các công thức và giá đã hẹn tới giờ (gọi ở pay_bill, add_bill_line, menu_for_sale và các hàm thực đơn)
create or replace function _menu_apply_due(p_shop uuid default null) returns void
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := coalesce(p_shop, app_shop_id()); r record;
begin
  if v_shop is null then return; end if;
  for r in select id from recipe_versions
            where shop_id = v_shop and status = 'scheduled' and effective_from <= now()
            order by effective_from, version_no loop
    perform _recipe_activate(r.id);
  end loop;
  for r in select id, size_id, new_price from price_changes
            where shop_id = v_shop and status = 'scheduled' and effective_from <= now()
            order by effective_from for update skip locked loop
    update menu_sizes set price = r.new_price where id = r.size_id;
    update price_changes set status = 'applied', applied_at = now() where id = r.id;
  end loop;
end $$;

-- ---------- 4) Đọc ----------
create or replace function menu_ingredients() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_owner();
  return jsonb_build_object(
    'cost_updated_at', (select max(unit_cost_updated_at) from ingredients where shop_id = app_shop_id()),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'id', i.id, 'name', i.name, 'unit', i.unit, 'group_name', i.group_name,
        'unit_cost', i.unit_cost, 'unit_cost_updated_at', i.unit_cost_updated_at) order by i.name)
      from ingredients i where i.shop_id = app_shop_id() and i.active), '[]'::jsonb));
end $$;

create or replace function menu_overview() returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_shop uuid := app_shop_id();
  v_low integer;
  v_week_from date;
  v_week_ts timestamptz;
  v_n integer;
begin
  perform _require_owner();
  perform _menu_apply_due(v_shop);
  v_low := _setting('menu_low_margin_pct', 30, v_shop);
  -- Tuần kinh doanh: từ thứ Hai 06:00 (giờ Việt Nam)
  v_week_from := date_trunc('week', (now() at time zone 'Asia/Ho_Chi_Minh') - interval '6 hours')::date;
  v_week_ts := (v_week_from + time '06:00') at time zone 'Asia/Ho_Chi_Minh';
  select count(*) into v_n from menu_items where shop_id = v_shop and not is_draft;

  return (
    with sold as (
      select bl.size_id, sum(bl.qty)::integer as q
        from bill_lines bl join bills b on b.id = bl.bill_id and b.status = 'paid'
       where bl.shop_id = v_shop and bl.voided_at is null and b.paid_at >= v_week_ts
       group by bl.size_id
    ), rc as (
      select rl.size_id, round(sum(rl.qty * i.unit_cost))::integer as cost,
             bool_and(i.unit_cost is not null) as known, count(*)::integer as n
        from recipe_lines rl join ingredients i on i.id = rl.ingredient_id
       where rl.shop_id = v_shop group by rl.size_id
    ), sz as (
      select ms.item_id,
             jsonb_agg(jsonb_build_object(
               'id', ms.id, 'name', ms.size_name, 'price', ms.price, 'active', ms.active,
               'has_recipe', coalesce(rc.n, 0) > 0,
               'cost', case when rc.known then rc.cost end,
               'cost_known', coalesce(rc.known, false),
               'recipe_version', (select max(v.version_no) from recipe_versions v where v.size_id = ms.id and v.status = 'active'),
               'scheduled_from', (select v.effective_from from recipe_versions v where v.size_id = ms.id and v.status = 'scheduled' order by v.version_no desc limit 1),
               'pending_price', (select p.new_price from price_changes p where p.size_id = ms.id and p.status = 'scheduled' order by p.created_at desc limit 1),
               'sold_week', coalesce(sold.q, 0)
             ) order by ms.price, ms.size_name) as sizes,
             sum(coalesce(sold.q, 0))::integer as sold_week
        from menu_sizes ms
        left join rc on rc.size_id = ms.id
        left join sold on sold.size_id = ms.id
       where ms.shop_id = v_shop
       group by ms.item_id
    ), ranked as (
      select mi.id, sz.sizes, coalesce(sz.sold_week, 0) as sold_week,
             rank() over (order by coalesce(sz.sold_week, 0) desc) as rk
        from menu_items mi left join sz on sz.item_id = mi.id
       where mi.shop_id = v_shop and not mi.is_draft
    )
    select jsonb_build_object(
      'low_margin_pct', v_low,
      'week_from', v_week_from,
      'week_to', v_week_from + 6,
      'cost_updated_at', (select max(unit_cost_updated_at) from ingredients where shop_id = v_shop),
      'categories', coalesce((select jsonb_agg(jsonb_build_object(
            'id', c.id, 'name', c.name, 'sort_order', c.sort_order,
            'item_count', (select count(*) from menu_items m where m.shop_id = v_shop
                            and lower(btrim(m.group_name)) = lower(btrim(c.name))))
            order by c.sort_order, c.name) from menu_categories c where c.shop_id = v_shop), '[]'::jsonb),
      'items', coalesce((select jsonb_agg(jsonb_build_object(
            'id', mi.id, 'name', mi.name, 'category', mi.group_name, 'active', mi.active,
            'is_draft', mi.is_draft, 'image_path', mi.image_path, 'description', mi.description,
            'sold_week', coalesce(sz.sold_week, 0),
            'best_seller', coalesce(sz.sold_week, 0) > 0
                           and (select rk from ranked where ranked.id = mi.id) <= case when v_n >= 4 then 2 else 1 end,
            'sizes', coalesce(sz.sizes, '[]'::jsonb))
            order by mi.is_draft desc, lower(mi.name))
          from menu_items mi left join sz on sz.item_id = mi.id where mi.shop_id = v_shop), '[]'::jsonb)
    )
  );
end $$;

create or replace function _menu_recipe_json(p_version uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'lines', coalesce(jsonb_agg(jsonb_build_object(
        'ingredient_id', i.id, 'name', i.name, 'unit', i.unit, 'qty', l.qty,
        'unit_cost', i.unit_cost,
        'line_cost', case when i.unit_cost is null then null else round(l.qty * i.unit_cost)::integer end)
        order by i.name), '[]'::jsonb),
    'cost', case when bool_and(i.unit_cost is not null) then round(sum(l.qty * i.unit_cost))::integer end,
    'cost_known', coalesce(bool_and(i.unit_cost is not null), false))
  from recipe_version_lines l join ingredients i on i.id = l.ingredient_id
 where l.version_id = p_version
$$;

create or replace function menu_item_detail(p_item uuid) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_item menu_items%rowtype; v_sizes jsonb;
begin
  perform _require_owner();
  perform _menu_apply_due(v_shop);
  select * into v_item from menu_items where id = p_item and shop_id = v_shop;
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', ms.id, 'name', ms.size_name, 'price', ms.price, 'active', ms.active,
      'ever_sold', exists (select 1 from bill_lines bl where bl.size_id = ms.id),
      'current', (select jsonb_build_object('version_id', v.id, 'version_no', v.version_no,
                         'effective_from', v.effective_from, 'applied_at', v.applied_at) || _menu_recipe_json(v.id)
                    from recipe_versions v where v.size_id = ms.id and v.status = 'active'),
      'scheduled', (select jsonb_build_object('version_id', v.id, 'version_no', v.version_no,
                         'effective_from', v.effective_from, 'created_at', v.created_at,
                         'created_by_name', (select s.full_name from staff s where s.id = v.created_by))
                         || _menu_recipe_json(v.id)
                    from recipe_versions v where v.size_id = ms.id and v.status = 'scheduled'
                    order by v.version_no desc limit 1),
      'pending_price', (select jsonb_build_object('change_id', p.id, 'new_price', p.new_price,
                         'effective_from', p.effective_from)
                    from price_changes p where p.size_id = ms.id and p.status = 'scheduled'
                    order by p.created_at desc limit 1)
    ) order by ms.price, ms.size_name), '[]'::jsonb)
    into v_sizes
    from menu_sizes ms where ms.item_id = p_item and ms.shop_id = v_shop;

  return jsonb_build_object(
    'item', jsonb_build_object('id', v_item.id, 'name', v_item.name, 'category', v_item.group_name,
        'active', v_item.active, 'is_draft', v_item.is_draft, 'description', v_item.description,
        'image_path', v_item.image_path),
    'low_margin_pct', _setting('menu_low_margin_pct', 30, v_shop),
    'sizes', v_sizes);
end $$;

create or replace function menu_recipe_versions(p_size uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_owner();
  if not exists (select 1 from menu_sizes where id = p_size and shop_id = app_shop_id()) then
    raise exception 'MENU_SIZE_NOT_FOUND';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', v.id, 'version_no', v.version_no, 'status', v.status,
      'effective_from', v.effective_from, 'applied_at', v.applied_at, 'created_at', v.created_at,
      'created_by_name', (select s.full_name from staff s where s.id = v.created_by), 'note', v.note)
      || _menu_recipe_json(v.id) order by v.version_no desc)
    from recipe_versions v where v.size_id = p_size and v.status <> 'cancelled'), '[]'::jsonb);
end $$;

create or replace function menu_item_history(p_item uuid, p_limit integer default 50) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare v_shop uuid := app_shop_id();
begin
  perform _require_owner();
  perform _menu_apply_due(v_shop);
  if not exists (select 1 from menu_items where id = p_item and shop_id = v_shop) then
    raise exception 'MENU_ITEM_NOT_FOUND';
  end if;
  return jsonb_build_object(
    'upcoming', coalesce((
      select jsonb_agg(x order by (x->>'effective_from')) from (
        select jsonb_build_object('kind', 'recipe', 'id', v.id, 'size_name', ms.size_name,
               'version_no', v.version_no, 'effective_from', v.effective_from, 'created_at', v.created_at,
               'actor_name', (select s.full_name from staff s where s.id = v.created_by)) as x
          from recipe_versions v join menu_sizes ms on ms.id = v.size_id
         where ms.item_id = p_item and v.status = 'scheduled'
        union all
        select jsonb_build_object('kind', 'price', 'id', p.id, 'size_name', ms.size_name,
               'old_price', p.old_price, 'new_price', p.new_price,
               'effective_from', p.effective_from, 'created_at', p.created_at,
               'actor_name', (select s.full_name from staff s where s.id = p.created_by))
          from price_changes p join menu_sizes ms on ms.id = p.size_id
         where ms.item_id = p_item and p.status = 'scheduled') u), '[]'::jsonb),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object('id', e.id, 'kind', e.kind, 'summary', e.summary, 'detail', e.detail,
               'actor_name', (select s.full_name from staff s where s.id = e.actor), 'created_at', e.created_at)
               order by e.created_at desc)
        from (select * from menu_events where item_id = p_item and shop_id = v_shop
               order by created_at desc limit greatest(1, least(coalesce(p_limit, 50), 200))) e), '[]'::jsonb));
end $$;

create or replace function menu_categories_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_owner();
  return coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'sort_order', c.sort_order,
      'item_count', (select count(*) from menu_items m where m.shop_id = c.shop_id
                      and lower(btrim(m.group_name)) = lower(btrim(c.name)))) order by c.sort_order, c.name)
    from menu_categories c where c.shop_id = app_shop_id()), '[]'::jsonb);
end $$;

-- ---------- 5) Ghi: món và size ----------
create or replace function menu_item_create(p_name text, p_category text, p_sizes jsonb, p_publish boolean default false)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_shop uuid := app_shop_id(); v_name text := btrim(coalesce(p_name, '')); v_cat text := nullif(btrim(coalesce(p_category, '')), '');
  v_item uuid; v_s jsonb; v_sname text; v_price integer; v_seen text[] := '{}';
begin
  perform _require_owner();
  if v_name = '' then raise exception 'MENU_NAME_REQUIRED'; end if;
  if exists (select 1 from menu_items where shop_id = v_shop and lower(btrim(name)) = lower(v_name)) then
    raise exception 'MENU_NAME_DUPLICATE';
  end if;
  if v_cat is not null then
    select name into v_cat from menu_categories where shop_id = v_shop and lower(btrim(name)) = lower(v_cat);
    if v_cat is null then raise exception 'CATEGORY_NOT_FOUND'; end if;
  end if;
  if p_sizes is null or jsonb_typeof(p_sizes) <> 'array' or jsonb_array_length(p_sizes) = 0 then
    raise exception 'MENU_SIZE_REQUIRED';
  end if;
  for v_s in select * from jsonb_array_elements(p_sizes) loop
    v_sname := btrim(coalesce(v_s->>'name', ''));
    if v_sname = '' then raise exception 'SIZE_NAME_REQUIRED'; end if;
    if lower(v_sname) = any (v_seen) then raise exception 'SIZE_NAME_DUPLICATE'; end if;
    v_seen := v_seen || lower(v_sname);
    v_price := (v_s->>'price')::integer;
    if v_price is null or v_price <= 0 then raise exception 'PRICE_INVALID'; end if;
  end loop;

  insert into menu_items (shop_id, name, group_name, active, is_draft)
  values (v_shop, v_name, v_cat, coalesce(p_publish, false), not coalesce(p_publish, false))
  returning id into v_item;
  for v_s in select * from jsonb_array_elements(p_sizes) loop
    insert into menu_sizes (shop_id, item_id, size_name, price, active)
    values (v_shop, v_item, btrim(v_s->>'name'), (v_s->>'price')::integer, true);
  end loop;
  perform _menu_event(v_item, null, 'created',
    case when coalesce(p_publish, false) then 'Tạo món và mở bán' else 'Lưu bản nháp (chưa bán)' end,
    jsonb_build_object('sizes', p_sizes));
  return v_item;
end $$;

create or replace function menu_item_update(p_item uuid, p_name text, p_category text, p_description text default null)
returns void
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_name text := btrim(coalesce(p_name, '')); v_cat text := nullif(btrim(coalesce(p_category, '')), ''); v_old menu_items%rowtype;
begin
  perform _require_owner();
  select * into v_old from menu_items where id = p_item and shop_id = v_shop for update;
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if v_name = '' then raise exception 'MENU_NAME_REQUIRED'; end if;
  if exists (select 1 from menu_items where shop_id = v_shop and id <> p_item and lower(btrim(name)) = lower(v_name)) then
    raise exception 'MENU_NAME_DUPLICATE';
  end if;
  if v_cat is not null then
    select name into v_cat from menu_categories where shop_id = v_shop and lower(btrim(name)) = lower(v_cat);
    if v_cat is null then raise exception 'CATEGORY_NOT_FOUND'; end if;
  end if;
  update menu_items set name = v_name, group_name = v_cat, description = nullif(btrim(coalesce(p_description, '')), '')
   where id = p_item;
  if v_old.name is distinct from v_name then
    perform _menu_event(p_item, null, 'update', 'Đổi tên từ "' || v_old.name || '" thành "' || v_name || '"');
  end if;
  if v_old.group_name is distinct from v_cat then
    perform _menu_event(p_item, null, 'category', 'Đổi nhóm món: ' || coalesce(v_old.group_name, 'Khác') || ' → ' || coalesce(v_cat, 'Khác'));
  end if;
end $$;

create or replace function menu_size_add(p_item uuid, p_name text, p_price integer) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_name text := btrim(coalesce(p_name, '')); v_id uuid; v_old menu_sizes%rowtype;
begin
  perform _require_owner();
  if not exists (select 1 from menu_items where id = p_item and shop_id = v_shop) then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if v_name = '' then raise exception 'SIZE_NAME_REQUIRED'; end if;
  if p_price is null or p_price <= 0 then raise exception 'PRICE_INVALID'; end if;
  select * into v_old from menu_sizes where item_id = p_item and lower(btrim(size_name)) = lower(v_name) for update;
  if found then
    if v_old.active then raise exception 'SIZE_NAME_DUPLICATE'; end if;
    -- size đã ẩn trước đó: bật lại (giữ lịch sử và công thức cũ) với giá mới
    update menu_sizes set active = true, price = p_price where id = v_old.id;
    perform _menu_event(p_item, v_old.id, 'update', 'Bật lại size ' || v_old.size_name || ' · giá ' || p_price);
    return v_old.id;
  end if;
  insert into menu_sizes (shop_id, item_id, size_name, price, active) values (v_shop, p_item, v_name, p_price, true)
  returning id into v_id;
  perform _menu_event(p_item, v_id, 'update', 'Thêm size ' || v_name || ' · giá ' || p_price);
  return v_id;
end $$;

-- Dữ liệu bán hàng không bị xóa: bỏ size = ẩn size (active = false), có thể bật lại bằng menu_size_add cùng tên
create or replace function menu_size_remove(p_size uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_ms menu_sizes%rowtype; v_left integer;
begin
  perform _require_owner();
  select * into v_ms from menu_sizes where id = p_size and shop_id = v_shop for update;
  if not found then raise exception 'MENU_SIZE_NOT_FOUND'; end if;
  if not v_ms.active then return; end if;
  select count(*) into v_left from menu_sizes where item_id = v_ms.item_id and active and id <> p_size;
  if v_left = 0 then raise exception 'LAST_SIZE'; end if;
  update menu_sizes set active = false where id = p_size;
  update recipe_versions set status = 'cancelled' where size_id = p_size and status = 'scheduled';
  update price_changes set status = 'cancelled' where size_id = p_size and status = 'scheduled';
  perform _menu_event(v_ms.item_id, p_size, 'status', 'Ngừng bán size ' || v_ms.size_name);
end $$;

create or replace function menu_item_set_active(p_item uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public as $$
declare v menu_items%rowtype;
begin
  perform _require_owner();
  select * into v from menu_items where id = p_item and shop_id = app_shop_id() for update;
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if v.is_draft then raise exception 'ITEM_IS_DRAFT'; end if;
  if v.active = coalesce(p_active, false) then return; end if;
  update menu_items set active = coalesce(p_active, false) where id = p_item;
  perform _menu_event(p_item, null, 'status',
    case when p_active then 'Mở bán lại' else 'Tạm ngừng bán' end,
    jsonb_build_object('from', case when v.active then 'Đang bán' else 'Ngừng bán' end,
                       'to', case when p_active then 'Đang bán' else 'Ngừng bán' end));
end $$;

create or replace function menu_item_publish(p_item uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v menu_items%rowtype;
begin
  perform _require_owner();
  select * into v from menu_items where id = p_item and shop_id = app_shop_id() for update;
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if not exists (select 1 from menu_sizes where item_id = p_item and active) then raise exception 'MENU_SIZE_REQUIRED'; end if;
  update menu_items set is_draft = false, active = true where id = p_item;
  perform _menu_event(p_item, null, 'status', 'Mở bán món');
end $$;

create or replace function menu_item_set_image(p_item uuid, p_path text) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform _require_owner();
  update menu_items set image_path = nullif(btrim(coalesce(p_path, '')), '') where id = p_item and shop_id = app_shop_id();
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  perform _menu_event(p_item, null, 'image', case when nullif(btrim(coalesce(p_path, '')), '') is null then 'Gỡ ảnh món' else 'Đổi ảnh món' end);
end $$;

-- ---------- 6) Ghi: công thức, giá ----------
create or replace function menu_recipe_save(p_size uuid, p_lines jsonb, p_effective timestamptz default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_shop uuid := app_shop_id(); v_ms menu_sizes%rowtype; v_eff timestamptz; v_no integer; v_id uuid;
  v_l jsonb; v_ing uuid; v_qty integer; v_seen uuid[] := '{}'; v_last uuid; v_same boolean; v_status text;
begin
  perform _require_owner();
  perform _menu_apply_due(v_shop);
  select * into v_ms from menu_sizes where id = p_size and shop_id = v_shop for update;
  if not found then raise exception 'MENU_SIZE_NOT_FOUND'; end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'RECIPE_EMPTY';
  end if;
  for v_l in select * from jsonb_array_elements(p_lines) loop
    v_ing := (v_l->>'ingredient_id')::uuid;
    v_qty := (v_l->>'qty')::integer;
    if not exists (select 1 from ingredients where id = v_ing and shop_id = v_shop and active) then
      raise exception 'INGREDIENT_NOT_FOUND';
    end if;
    if v_qty is null or v_qty <= 0 then raise exception 'QTY_INVALID'; end if;
    if v_ing = any (v_seen) then raise exception 'INGREDIENT_DUPLICATE'; end if;
    v_seen := v_seen || v_ing;
  end loop;

  v_eff := coalesce(p_effective, now());
  if v_eff > now() + interval '365 days' then raise exception 'EFFECTIVE_INVALID'; end if;
  if v_eff < now() then v_eff := now(); end if;

  -- Không đổi gì so với bản mới nhất (đang dùng hoặc đã hẹn) thì không tạo phiên bản
  select id into v_last from recipe_versions
   where size_id = p_size and status in ('active','scheduled') order by version_no desc limit 1;
  if v_last is not null then
    select not exists (
             (select ingredient_id, qty from recipe_version_lines where version_id = v_last
              except select (e->>'ingredient_id')::uuid, (e->>'qty')::integer from jsonb_array_elements(p_lines) e)
             union all
             (select (e->>'ingredient_id')::uuid, (e->>'qty')::integer from jsonb_array_elements(p_lines) e
              except select ingredient_id, qty from recipe_version_lines where version_id = v_last))
      into v_same;
    if v_same then raise exception 'RECIPE_UNCHANGED'; end if;
  end if;

  update recipe_versions set status = 'cancelled' where size_id = p_size and status = 'scheduled';
  select coalesce(max(version_no), 0) + 1 into v_no from recipe_versions where size_id = p_size;
  insert into recipe_versions (shop_id, size_id, version_no, status, effective_from, note, created_by)
  values (v_shop, p_size, v_no, 'scheduled', v_eff, nullif(btrim(coalesce(p_note, '')), ''), app_staff_id())
  returning id into v_id;
  insert into recipe_version_lines (version_id, ingredient_id, qty)
  select v_id, (e->>'ingredient_id')::uuid, (e->>'qty')::integer from jsonb_array_elements(p_lines) e;
  if v_eff <= now() then perform _recipe_activate(v_id); end if;
  select status into v_status from recipe_versions where id = v_id;

  perform _menu_event(v_ms.item_id, p_size, 'recipe',
    'Công thức size ' || v_ms.size_name || ' v' || v_no || case when v_status = 'active' then ' đang dùng' else ' đã lên lịch' end,
    jsonb_build_object('size_name', v_ms.size_name, 'version_no', v_no, 'status', v_status, 'effective_from', v_eff));
  return jsonb_build_object('version_id', v_id, 'version_no', v_no, 'status', v_status, 'effective_from', v_eff);
end $$;

create or replace function menu_recipe_cancel(p_version uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v recipe_versions%rowtype; v_ms menu_sizes%rowtype;
begin
  perform _require_owner();
  select * into v from recipe_versions where id = p_version and shop_id = app_shop_id() for update;
  if not found then raise exception 'RECIPE_VERSION_NOT_FOUND'; end if;
  if v.status <> 'scheduled' then raise exception 'RECIPE_VERSION_NOT_SCHEDULED'; end if;
  update recipe_versions set status = 'cancelled' where id = p_version;
  select * into v_ms from menu_sizes where id = v.size_id;
  perform _menu_event(v_ms.item_id, v.size_id, 'recipe', 'Hủy lịch công thức size ' || v_ms.size_name || ' v' || v.version_no);
end $$;

create or replace function menu_price_change(p_changes jsonb, p_effective timestamptz default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_shop uuid := app_shop_id(); v_eff timestamptz; v_c jsonb; v_ms menu_sizes%rowtype; v_new integer;
  v_now boolean; v_n integer := 0; v_item uuid; v_log jsonb := '[]'::jsonb;
begin
  perform _require_owner();
  perform _menu_apply_due(v_shop);
  if p_changes is null or jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes) = 0 then
    raise exception 'PRICE_UNCHANGED';
  end if;
  v_eff := coalesce(p_effective, now());
  if v_eff > now() + interval '365 days' then raise exception 'EFFECTIVE_INVALID'; end if;
  if v_eff < now() then v_eff := now(); end if;
  v_now := v_eff <= now();

  for v_c in select * from jsonb_array_elements(p_changes) loop
    select * into v_ms from menu_sizes where id = (v_c->>'size_id')::uuid and shop_id = v_shop for update;
    if not found then raise exception 'MENU_SIZE_NOT_FOUND'; end if;
    v_new := (v_c->>'price')::integer;
    if v_new is null or v_new <= 0 then raise exception 'PRICE_INVALID'; end if;
    if v_new = v_ms.price and not exists (select 1 from price_changes where size_id = v_ms.id and status = 'scheduled') then
      continue;
    end if;
    update price_changes set status = 'cancelled' where size_id = v_ms.id and status = 'scheduled';
    if v_new = v_ms.price then continue; end if;
    insert into price_changes (shop_id, size_id, old_price, new_price, status, effective_from, applied_at, created_by)
    values (v_shop, v_ms.id, v_ms.price, v_new, case when v_now then 'applied' else 'scheduled' end, v_eff,
            case when v_now then now() end, app_staff_id());
    if v_now then update menu_sizes set price = v_new where id = v_ms.id; end if;
    v_n := v_n + 1; v_item := v_ms.item_id;
    v_log := v_log || jsonb_build_object('size_id', v_ms.id, 'size_name', v_ms.size_name, 'old', v_ms.price, 'new', v_new);
  end loop;
  if v_n = 0 then raise exception 'PRICE_UNCHANGED'; end if;
  perform _menu_event(v_item, null, 'price',
    case when v_now then 'Đổi giá bán' else 'Hẹn đổi giá bán' end,
    jsonb_build_object('changes', v_log, 'effective_from', v_eff, 'applied', v_now));
  return jsonb_build_object('applied', v_now, 'effective_from', v_eff, 'count', v_n);
end $$;

create or replace function menu_price_cancel(p_change uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v price_changes%rowtype; v_ms menu_sizes%rowtype;
begin
  perform _require_owner();
  select * into v from price_changes where id = p_change and shop_id = app_shop_id() for update;
  if not found then raise exception 'PRICE_CHANGE_NOT_FOUND'; end if;
  if v.status <> 'scheduled' then raise exception 'PRICE_CHANGE_NOT_SCHEDULED'; end if;
  update price_changes set status = 'cancelled' where id = p_change;
  select * into v_ms from menu_sizes where id = v.size_id;
  perform _menu_event(v_ms.item_id, v.size_id, 'price', 'Hủy lịch đổi giá size ' || v_ms.size_name);
end $$;

create or replace function set_ingredient_cost(p_ingredient uuid, p_cost numeric) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform _require_owner();
  if p_cost is not null and p_cost < 0 then raise exception 'COST_INVALID'; end if;
  update ingredients set unit_cost = p_cost, unit_cost_updated_at = now()
   where id = p_ingredient and shop_id = app_shop_id();
  if not found then raise exception 'INGREDIENT_NOT_FOUND'; end if;
end $$;

create or replace function menu_set_low_margin(p_pct integer) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform _require_owner();
  if p_pct is null or p_pct < 0 or p_pct > 90 then raise exception 'SETTING_INVALID'; end if;
  insert into app_settings (shop_id, key, value_int, description)
  values (app_shop_id(), 'menu_low_margin_pct', p_pct, 'Lãi gộp của một size thấp hơn mức % này thì cảnh báo "Lãi thấp"')
  on conflict (shop_id, key) do update set value_int = excluded.value_int;
end $$;

-- ---------- 7) Danh mục ----------
create or replace function menu_category_add(p_name text) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_name text := btrim(coalesce(p_name, '')); v_id uuid;
begin
  perform _require_owner();
  if v_name = '' then raise exception 'CATEGORY_NAME_REQUIRED'; end if;
  if exists (select 1 from menu_categories where shop_id = app_shop_id() and lower(btrim(name)) = lower(v_name)) then
    raise exception 'CATEGORY_DUPLICATE';
  end if;
  insert into menu_categories (shop_id, name, sort_order)
  values (app_shop_id(), v_name, coalesce((select max(sort_order) from menu_categories where shop_id = app_shop_id()), 0) + 1)
  returning id into v_id;
  return v_id;
end $$;

create or replace function menu_category_rename(p_id uuid, p_name text) returns void
language plpgsql security definer set search_path = public as $$
declare v_name text := btrim(coalesce(p_name, '')); v_old text; v_shop uuid := app_shop_id();
begin
  perform _require_owner();
  select name into v_old from menu_categories where id = p_id and shop_id = v_shop for update;
  if not found then raise exception 'CATEGORY_NOT_FOUND'; end if;
  if v_name = '' then raise exception 'CATEGORY_NAME_REQUIRED'; end if;
  if exists (select 1 from menu_categories where shop_id = v_shop and id <> p_id and lower(btrim(name)) = lower(v_name)) then
    raise exception 'CATEGORY_DUPLICATE';
  end if;
  update menu_categories set name = v_name where id = p_id;
  update menu_items set group_name = v_name where shop_id = v_shop and lower(btrim(group_name)) = lower(btrim(v_old));
end $$;

create or replace function menu_category_reorder(p_ids uuid[]) returns void
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_total integer;
begin
  perform _require_owner();
  select count(*) into v_total from menu_categories where shop_id = v_shop;
  if p_ids is null or coalesce(array_length(p_ids, 1), 0) <> v_total
     or (select count(distinct x) from unnest(p_ids) x) <> v_total
     or exists (select 1 from unnest(p_ids) x where not exists (select 1 from menu_categories c where c.id = x and c.shop_id = v_shop)) then
    raise exception 'CATEGORY_ORDER_INVALID';
  end if;
  update menu_categories c set sort_order = o.n::integer
    from unnest(p_ids) with ordinality as o(id, n) where c.id = o.id;
end $$;

-- ---------- 8) Sao chép ----------
create or replace function _menu_copy_item(p_item uuid, p_to_shop uuid, p_name text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_from uuid; v_src menu_items%rowtype; v_new uuid; v_cat text; v_s record; v_size uuid; v_ver uuid;
  v_lines integer := 0; v_skipped text[] := '{}'; v_l record; v_ing uuid;
begin
  select * into v_src from menu_items where id = p_item;
  v_from := v_src.shop_id;
  if exists (select 1 from menu_items where shop_id = p_to_shop and lower(btrim(name)) = lower(btrim(p_name))) then
    raise exception 'MENU_NAME_DUPLICATE';
  end if;
  v_cat := v_src.group_name;
  if v_cat is not null and not exists (select 1 from menu_categories where shop_id = p_to_shop and lower(btrim(name)) = lower(btrim(v_cat))) then
    insert into menu_categories (shop_id, name, sort_order)
    values (p_to_shop, v_cat, coalesce((select max(sort_order) from menu_categories where shop_id = p_to_shop), 0) + 1);
  end if;
  insert into menu_items (shop_id, name, group_name, active, is_draft, description, image_path)
  values (p_to_shop, btrim(p_name), v_cat, false, true, v_src.description,
          case when p_to_shop = v_from then v_src.image_path end)
  returning id into v_new;
  for v_s in select * from menu_sizes where item_id = p_item and active order by price, size_name loop
    insert into menu_sizes (shop_id, item_id, size_name, price, active)
    values (p_to_shop, v_new, v_s.size_name, v_s.price, true) returning id into v_size;
    v_ver := null;
    for v_l in select rl.qty, i.name, i.unit, rl.ingredient_id from recipe_lines rl join ingredients i on i.id = rl.ingredient_id
                where rl.size_id = v_s.id loop
      if p_to_shop = v_from then v_ing := v_l.ingredient_id;
      else
        select id into v_ing from ingredients
         where shop_id = p_to_shop and active and unit = v_l.unit and lower(btrim(name)) = lower(btrim(v_l.name));
        if v_ing is null then v_skipped := array_append(v_skipped, v_l.name); continue; end if;
      end if;
      if v_ver is null then
        insert into recipe_versions (shop_id, size_id, version_no, status, effective_from, applied_at, created_by)
        values (p_to_shop, v_size, 1, 'active', now(), now(), app_staff_id()) returning id into v_ver;
      end if;
      insert into recipe_version_lines (version_id, ingredient_id, qty) values (v_ver, v_ing, v_l.qty);
      perform set_config('fore.recipe_apply', 'on', true);
      insert into recipe_lines (shop_id, size_id, ingredient_id, qty) values (p_to_shop, v_size, v_ing, v_l.qty);
      perform set_config('fore.recipe_apply', 'off', true);
      v_lines := v_lines + 1;
    end loop;
  end loop;
  return jsonb_build_object('item_id', v_new, 'copied_lines', v_lines, 'skipped_ingredients', to_jsonb(v_skipped));
end $$;

create or replace function menu_item_copy(p_item uuid, p_new_name text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_r jsonb; v_name text := btrim(coalesce(p_new_name, ''));
begin
  perform _require_owner();
  if not exists (select 1 from menu_items where id = p_item and shop_id = v_shop) then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if v_name = '' then raise exception 'MENU_NAME_REQUIRED'; end if;
  v_r := _menu_copy_item(p_item, v_shop, v_name);
  perform _menu_event((v_r->>'item_id')::uuid, null, 'copy', 'Tạo bản sao từ "' || (select name from menu_items where id = p_item) || '" (bản nháp)');
  return v_r;
end $$;

create or replace function menu_copy_targets() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_owner();
  return coalesce((select jsonb_agg(jsonb_build_object('shop_id', s.shop_id, 'name', sh.name) order by sh.name)
    from staff s join shops sh on sh.id = s.shop_id
   where s.auth_user_id = auth.uid() and s.active and s.role = 'owner' and s.shop_id <> app_shop_id()), '[]'::jsonb);
end $$;

create or replace function menu_item_copy_to_shop(p_item uuid, p_shop uuid, p_new_name text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_src menu_items%rowtype; v_r jsonb; v_name text;
begin
  perform _require_owner();
  select * into v_src from menu_items where id = p_item and shop_id = app_shop_id();
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if p_shop is null or p_shop = app_shop_id() or not exists (
       select 1 from staff s where s.auth_user_id = auth.uid() and s.active and s.role = 'owner' and s.shop_id = p_shop) then
    raise exception 'OWNER_ONLY';
  end if;
  v_name := coalesce(nullif(btrim(coalesce(p_new_name, '')), ''), v_src.name);
  v_r := _menu_copy_item(p_item, p_shop, v_name);
  insert into menu_events (shop_id, item_id, kind, summary, detail, actor)
  values (p_shop, (v_r->>'item_id')::uuid, 'copy', 'Sao chép từ quán khác (bản nháp)', v_r,
          (select s.id from staff s where s.auth_user_id = auth.uid() and s.shop_id = p_shop and s.active limit 1));
  perform _menu_event(p_item, null, 'copy', 'Sao chép sang quán khác');
  return v_r;
end $$;

-- ---------- 9) Ảnh món (Supabase Storage; bỏ qua nếu không có schema storage, ví dụ khi test) ----------
do $$
begin
  if to_regclass('storage.buckets') is not null and to_regclass('storage.objects') is not null then
    insert into storage.buckets (id, name, public) values ('menu-images', 'menu-images', true) on conflict (id) do nothing;
    execute 'drop policy if exists menu_images_read on storage.objects';
    execute 'create policy menu_images_read on storage.objects for select using (bucket_id = ''menu-images'')';
    execute 'drop policy if exists menu_images_write on storage.objects';
    execute 'create policy menu_images_write on storage.objects for all to authenticated
             using (bucket_id = ''menu-images'' and (storage.foldername(name))[1] = (select app_shop_id())::text and (select app_is_owner()))
             with check (bucket_id = ''menu-images'' and (storage.foldername(name))[1] = (select app_shop_id())::text and (select app_is_owner()))';
  end if;
end $$;

-- ---------- 10) Quyền gọi ----------
revoke all on function
  menu_ingredients(), menu_overview(), menu_item_detail(uuid), menu_recipe_versions(uuid), menu_item_history(uuid, integer),
  menu_categories_list(), menu_item_create(text, text, jsonb, boolean), menu_item_update(uuid, text, text, text),
  menu_size_add(uuid, text, integer), menu_size_remove(uuid), menu_item_set_active(uuid, boolean), menu_item_publish(uuid),
  menu_item_set_image(uuid, text), menu_recipe_save(uuid, jsonb, timestamptz, text),
  menu_recipe_cancel(uuid), menu_price_change(jsonb, timestamptz), menu_price_cancel(uuid), set_ingredient_cost(uuid, numeric),
  menu_set_low_margin(integer), menu_category_add(text), menu_category_rename(uuid, text), menu_category_reorder(uuid[]),
  menu_item_copy(uuid, text), menu_copy_targets(), menu_item_copy_to_shop(uuid, uuid, text)
  from public, anon;
grant execute on function
  menu_ingredients(), menu_overview(), menu_item_detail(uuid), menu_recipe_versions(uuid), menu_item_history(uuid, integer),
  menu_categories_list(), menu_item_create(text, text, jsonb, boolean), menu_item_update(uuid, text, text, text),
  menu_size_add(uuid, text, integer), menu_size_remove(uuid), menu_item_set_active(uuid, boolean), menu_item_publish(uuid),
  menu_item_set_image(uuid, text), menu_recipe_save(uuid, jsonb, timestamptz, text),
  menu_recipe_cancel(uuid), menu_price_change(jsonb, timestamptz), menu_price_cancel(uuid), set_ingredient_cost(uuid, numeric),
  menu_set_low_margin(integer), menu_category_add(text), menu_category_rename(uuid, text), menu_category_reorder(uuid[]),
  menu_item_copy(uuid, text), menu_copy_targets(), menu_item_copy_to_shop(uuid, uuid, text)
  to authenticated;
revoke all on function _menu_event(uuid, uuid, text, text, jsonb), _recipe_at(uuid, timestamptz), _recipe_activate(uuid),
  _menu_apply_due(uuid), _menu_recipe_json(uuid), _menu_copy_item(uuid, uuid, text) from public, anon, authenticated;

-- >>> SOURCE: database/06_menu_options.sql
-- Fore · 06_menu_options.sql · TOPPING và TÙY CHỌN PHA CHẾ của món; sao chép món có đối chiếu nguyên liệu
-- Áp dụng SAU 05_menu_management.sql. Chạy lại nhiều lần an toàn.
--
-- Mô hình (mỗi quán riêng):
--   · menu_toppings: topping của quán (giá bán thêm, định lượng + nguyên liệu tùy chọn để tính vốn).
--   · menu_item_toppings: món nào được bán kèm topping nào; giới hạn "tối đa N loại, mỗi loại M phần" nằm trên menu_items.
--   · menu_option_groups / menu_option_choices: nhóm tùy chọn pha chế của món (mức đá, mức đường...), áp dụng cho mọi size.
--     Mặc định chỉ là CHỈ DẪN CHO BARISTA: không đổi giá, không đổi lượng trừ kho. Chỉ khi một lựa chọn có "định lượng riêng"
--     (ingredient_id + qty) thì mới được tính vốn riêng.
--   · Không xóa cứng: tắt bằng cột active.
-- LƯU Ý: phần BÁN HÀNG (nhân viên chọn topping/tùy chọn khi gọi món, trừ kho theo topping) CHƯA nối; lần này chỉ là
--   cấu hình + xem trước của chủ quán.

-- ---------- 1) Bảng ----------
alter table menu_items add column if not exists topping_max_kinds integer not null default 2 check (topping_max_kinds >= 1);
alter table menu_items add column if not exists topping_max_portions integer not null default 1 check (topping_max_portions >= 1);

create table if not exists menu_toppings (
  id            uuid primary key default gen_random_uuid(),
  shop_id       uuid not null default app_shop_id() references shops(id),
  name          text not null check (char_length(btrim(name)) >= 1),
  price         integer not null default 0 check (price >= 0),
  ingredient_id uuid references ingredients(id),
  qty           integer check (qty is null or qty > 0),
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  check ((ingredient_id is null) = (qty is null))
);
create unique index if not exists menu_toppings_name_uq on menu_toppings (shop_id, lower(btrim(name)));

create table if not exists menu_item_toppings (
  item_id    uuid not null references menu_items(id),
  topping_id uuid not null references menu_toppings(id),
  shop_id    uuid not null default app_shop_id() references shops(id),
  active     boolean not null default true,
  primary key (item_id, topping_id)
);

create table if not exists menu_option_groups (
  id         uuid primary key default gen_random_uuid(),
  shop_id    uuid not null default app_shop_id() references shops(id),
  item_id    uuid not null references menu_items(id),
  name       text not null check (char_length(btrim(name)) >= 1),
  required   boolean not null default true,
  active     boolean not null default true,
  sort_order integer not null default 0
);
create index if not exists menu_option_groups_item_idx on menu_option_groups (item_id);

create table if not exists menu_option_choices (
  id            uuid primary key default gen_random_uuid(),
  group_id      uuid not null references menu_option_groups(id),
  shop_id       uuid not null default app_shop_id() references shops(id),
  name          text not null check (char_length(btrim(name)) >= 1),
  is_default    boolean not null default false,
  price_delta   integer not null default 0 check (price_delta >= 0),
  ingredient_id uuid references ingredients(id),
  qty           integer check (qty is null or qty > 0),
  active        boolean not null default true,
  sort_order    integer not null default 0,
  check ((ingredient_id is null) = (qty is null))
);

alter table menu_toppings       enable row level security;
alter table menu_item_toppings  enable row level security;
alter table menu_option_groups  enable row level security;
alter table menu_option_choices enable row level security;
drop policy if exists menu_toppings_read on menu_toppings;
create policy menu_toppings_read on menu_toppings for select to authenticated using (shop_id = (select app_shop_id()));
drop policy if exists menu_item_toppings_read on menu_item_toppings;
create policy menu_item_toppings_read on menu_item_toppings for select to authenticated using (shop_id = (select app_shop_id()));
drop policy if exists menu_option_groups_read on menu_option_groups;
create policy menu_option_groups_read on menu_option_groups for select to authenticated using (shop_id = (select app_shop_id()));
drop policy if exists menu_option_choices_read on menu_option_choices;
create policy menu_option_choices_read on menu_option_choices for select to authenticated using (shop_id = (select app_shop_id()));

-- ---------- 2) Topping ----------
create or replace function _menu_topping_json(p_id uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', t.id, 'name', t.name, 'price', t.price, 'active', t.active,
    'ingredient_id', t.ingredient_id, 'ingredient_name', i.name, 'unit', i.unit, 'qty', t.qty,
    'unit_cost', i.unit_cost,
    'cost', case when t.ingredient_id is null then 0
                 when i.unit_cost is null then null else round(t.qty * i.unit_cost)::integer end,
    'cost_known', t.ingredient_id is null or i.unit_cost is not null)
  from menu_toppings t left join ingredients i on i.id = t.ingredient_id
 where t.id = p_id
$$;

create or replace function menu_toppings_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_owner();
  return coalesce((select jsonb_agg(_menu_topping_json(t.id) || jsonb_build_object(
      'used_by', (select count(*) from menu_item_toppings x where x.topping_id = t.id and x.active)) order by t.active desc, t.name)
    from menu_toppings t where t.shop_id = app_shop_id()), '[]'::jsonb);
end $$;

create or replace function menu_topping_save(p_id uuid, p_name text, p_price integer, p_ingredient uuid, p_qty integer, p_active boolean default true)
returns uuid
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_name text := btrim(coalesce(p_name, '')); v_id uuid := p_id;
begin
  perform _require_owner();
  if v_name = '' then raise exception 'TOPPING_NAME_REQUIRED'; end if;
  if p_price is null or p_price < 0 then raise exception 'PRICE_INVALID'; end if;
  if (p_ingredient is null) <> (p_qty is null) or (p_qty is not null and p_qty <= 0) then raise exception 'QTY_INVALID'; end if;
  if p_ingredient is not null and not exists (select 1 from ingredients where id = p_ingredient and shop_id = v_shop and active) then
    raise exception 'INGREDIENT_NOT_FOUND';
  end if;
  if exists (select 1 from menu_toppings where shop_id = v_shop and lower(btrim(name)) = lower(v_name) and id is distinct from p_id) then
    raise exception 'TOPPING_DUPLICATE';
  end if;
  if p_id is null then
    insert into menu_toppings (shop_id, name, price, ingredient_id, qty, active)
    values (v_shop, v_name, p_price, p_ingredient, p_qty, coalesce(p_active, true)) returning id into v_id;
  else
    update menu_toppings set name = v_name, price = p_price, ingredient_id = p_ingredient, qty = p_qty, active = coalesce(p_active, true)
     where id = p_id and shop_id = v_shop;
    if not found then raise exception 'TOPPING_NOT_FOUND'; end if;
  end if;
  return v_id;
end $$;

-- ---------- 3) Topping + tùy chọn của một món ----------
create or replace function menu_item_extras(p_item uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_item menu_items%rowtype;
begin
  perform _require_owner();
  select * into v_item from menu_items where id = p_item and shop_id = app_shop_id();
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  return jsonb_build_object(
    'item_id', v_item.id,
    'topping_max_kinds', v_item.topping_max_kinds,
    'topping_max_portions', v_item.topping_max_portions,
    'toppings', coalesce((
      select jsonb_agg(_menu_topping_json(t.id) || jsonb_build_object(
               'selected', coalesce((select x.active from menu_item_toppings x where x.item_id = p_item and x.topping_id = t.id), false))
             order by t.active desc, t.name)
        from menu_toppings t where t.shop_id = app_shop_id()), '[]'::jsonb),
    'groups', coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', g.id, 'name', g.name, 'required', g.required, 'active', g.active,
          'choices', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', c.id, 'name', c.name, 'is_default', c.is_default, 'price_delta', c.price_delta,
                'ingredient_id', c.ingredient_id, 'ingredient_name', i.name, 'unit', i.unit, 'qty', c.qty,
                'unit_cost', i.unit_cost, 'active', c.active) order by c.sort_order, c.name)
              from menu_option_choices c left join ingredients i on i.id = c.ingredient_id
             where c.group_id = g.id and c.active), '[]'::jsonb)) order by g.sort_order, g.name)
        from menu_option_groups g where g.item_id = p_item and g.active), '[]'::jsonb));
end $$;

create or replace function menu_item_toppings_save(p_item uuid, p_ids uuid[], p_max_kinds integer, p_max_portions integer)
returns void
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_n integer; v_names text;
begin
  perform _require_owner();
  if not exists (select 1 from menu_items where id = p_item and shop_id = v_shop) then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  p_ids := coalesce(p_ids, '{}');
  if p_max_kinds is null or p_max_kinds < 1 or p_max_portions is null or p_max_portions < 1 then raise exception 'TOPPING_LIMIT_INVALID'; end if;
  select count(*) into v_n from menu_toppings where shop_id = v_shop and id = any (p_ids);
  if v_n <> (select count(distinct x) from unnest(p_ids) x) then raise exception 'TOPPING_NOT_FOUND'; end if;
  if p_max_kinds > greatest(v_n, 1) then raise exception 'TOPPING_LIMIT_INVALID'; end if;
  update menu_item_toppings set active = false where item_id = p_item and not (topping_id = any (p_ids));
  insert into menu_item_toppings (item_id, topping_id, shop_id, active)
  select p_item, x, v_shop, true from unnest(p_ids) x
  on conflict (item_id, topping_id) do update set active = true;
  update menu_items set topping_max_kinds = p_max_kinds, topping_max_portions = p_max_portions where id = p_item;
  select string_agg(t.name, ', ' order by t.name) into v_names from menu_toppings t where t.id = any (p_ids);
  perform _menu_event(p_item, null, 'topping',
    case when v_n = 0 then 'Tắt topping bán kèm' else 'Topping bán kèm: ' || v_names || ' (tối đa ' || p_max_kinds || ' loại, ' || p_max_portions || ' phần/loại)' end);
end $$;

-- Lưu TOÀN BỘ nhóm tùy chọn của món. Nhóm/lựa chọn không còn trong danh sách bị tắt (không xóa).
-- p_groups: [{id?, name, required, choices:[{id?, name, is_default, price_delta?, ingredient_id?, qty?}]}]
create or replace function menu_item_options_save(p_item uuid, p_groups jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_shop uuid := app_shop_id(); g jsonb; c jsonb; v_gid uuid; v_cid uuid; v_gi integer := 0; v_ci integer;
  v_name text; v_cname text; v_defaults integer; v_ing uuid; v_qty integer; v_required boolean;
  v_keep_g uuid[] := '{}'; v_keep_c uuid[]; v_seen_g text[] := '{}'; v_seen_c text[];
begin
  perform _require_owner();
  if not exists (select 1 from menu_items where id = p_item and shop_id = v_shop) then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if p_groups is null or jsonb_typeof(p_groups) <> 'array' then raise exception 'OPTION_INVALID'; end if;
  for g in select * from jsonb_array_elements(p_groups) loop
    v_gi := v_gi + 1;
    v_name := btrim(coalesce(g->>'name', ''));
    if v_name = '' then raise exception 'OPTION_GROUP_NAME_REQUIRED'; end if;
    if lower(v_name) = any (v_seen_g) then raise exception 'OPTION_GROUP_DUPLICATE'; end if;
    v_seen_g := array_append(v_seen_g, lower(v_name));
    v_required := coalesce((g->>'required')::boolean, true);
    if jsonb_array_length(coalesce(g->'choices', '[]')) < 1 then raise exception 'OPTION_CHOICE_REQUIRED'; end if;
    select count(*) into v_defaults from jsonb_array_elements(g->'choices') x where coalesce((x->>'is_default')::boolean, false);
    if v_required and v_defaults <> 1 then raise exception 'OPTION_DEFAULT_REQUIRED'; end if;
    if not v_required and v_defaults > 1 then raise exception 'OPTION_DEFAULT_REQUIRED'; end if;
    if nullif(g->>'id', '') is not null then
      v_gid := (g->>'id')::uuid;
      update menu_option_groups set name = v_name, required = v_required, active = true, sort_order = v_gi
       where id = v_gid and item_id = p_item and shop_id = v_shop;
      if not found then raise exception 'OPTION_NOT_FOUND'; end if;
    else
      insert into menu_option_groups (shop_id, item_id, name, required, sort_order) values (v_shop, p_item, v_name, v_required, v_gi)
      returning id into v_gid;
    end if;
    v_keep_g := array_append(v_keep_g, v_gid);
    v_keep_c := '{}'; v_seen_c := '{}'; v_ci := 0;
    for c in select * from jsonb_array_elements(g->'choices') loop
      v_ci := v_ci + 1;
      v_cname := btrim(coalesce(c->>'name', ''));
      if v_cname = '' then raise exception 'OPTION_CHOICE_NAME_REQUIRED'; end if;
      if lower(v_cname) = any (v_seen_c) then raise exception 'OPTION_CHOICE_DUPLICATE'; end if;
      v_seen_c := array_append(v_seen_c, lower(v_cname));
      v_ing := nullif(c->>'ingredient_id', '')::uuid;
      v_qty := nullif(c->>'qty', '')::integer;
      if (v_ing is null) <> (v_qty is null) or (v_qty is not null and v_qty <= 0) then raise exception 'QTY_INVALID'; end if;
      if v_ing is not null and not exists (select 1 from ingredients where id = v_ing and shop_id = v_shop and active) then
        raise exception 'INGREDIENT_NOT_FOUND';
      end if;
      if coalesce((c->>'price_delta')::integer, 0) < 0 then raise exception 'PRICE_INVALID'; end if;
      if nullif(c->>'id', '') is not null then
        v_cid := (c->>'id')::uuid;
        update menu_option_choices set name = v_cname, is_default = coalesce((c->>'is_default')::boolean, false),
               price_delta = coalesce((c->>'price_delta')::integer, 0), ingredient_id = v_ing, qty = v_qty, active = true, sort_order = v_ci
         where id = v_cid and group_id = v_gid and shop_id = v_shop;
        if not found then raise exception 'OPTION_NOT_FOUND'; end if;
      else
        insert into menu_option_choices (group_id, shop_id, name, is_default, price_delta, ingredient_id, qty, sort_order)
        values (v_gid, v_shop, v_cname, coalesce((c->>'is_default')::boolean, false), coalesce((c->>'price_delta')::integer, 0), v_ing, v_qty, v_ci)
        returning id into v_cid;
      end if;
      v_keep_c := array_append(v_keep_c, v_cid);
    end loop;
    update menu_option_choices set active = false where group_id = v_gid and not (id = any (v_keep_c));
  end loop;
  update menu_option_groups set active = false where item_id = p_item and not (id = any (v_keep_g));
  perform _menu_event(p_item, null, 'option',
    case when v_gi = 0 then 'Tắt các tùy chọn pha chế' else 'Cập nhật tùy chọn pha chế (' || v_gi || ' nhóm)' end);
end $$;

-- ---------- 4) Sao chép món: xem trước đối chiếu + sao chép có ánh xạ nguyên liệu ----------
-- Xem trước: mỗi dòng công thức của món nguồn và nguyên liệu khớp ở quán nhận (cùng tên + đơn vị), danh sách nguyên liệu
-- của quán nhận để chủ chọn tay, và tên món có bị trùng không.
create or replace function menu_copy_preview(p_item uuid, p_shop uuid, p_new_name text default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_src menu_items%rowtype; v_name text;
begin
  perform _require_owner();
  select * into v_src from menu_items where id = p_item and shop_id = app_shop_id();
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if p_shop is distinct from app_shop_id() and not exists (
       select 1 from staff s where s.auth_user_id = auth.uid() and s.active and s.role = 'owner' and s.shop_id = p_shop) then
    raise exception 'OWNER_ONLY';
  end if;
  v_name := coalesce(nullif(btrim(coalesce(p_new_name, '')), ''), v_src.name);
  return jsonb_build_object(
    'name_taken', exists (select 1 from menu_items where shop_id = p_shop and lower(btrim(name)) = lower(btrim(v_name))),
    'category', v_src.group_name,
    'category_exists', v_src.group_name is null or exists (select 1 from menu_categories where shop_id = p_shop and lower(btrim(name)) = lower(btrim(v_src.group_name))),
    'sizes', coalesce((select jsonb_agg(jsonb_build_object('name', s.size_name, 'price', s.price) order by s.price, s.size_name)
                         from menu_sizes s where s.item_id = p_item and s.active), '[]'::jsonb),
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
          'ingredient_id', x.ingredient_id, 'name', x.name, 'unit', x.unit, 'qty', x.qty, 'sizes', x.sizes,
          'match_id', m.id, 'match_name', m.name) order by x.name)
        from (select rl.ingredient_id, i.name, i.unit, max(rl.qty) as qty,
                     jsonb_agg(ms.size_name order by ms.price) as sizes
                from menu_sizes ms join recipe_lines rl on rl.size_id = ms.id join ingredients i on i.id = rl.ingredient_id
               where ms.item_id = p_item and ms.active
               group by rl.ingredient_id, i.name, i.unit) x
        left join lateral (select d.id, d.name from ingredients d
                            where d.shop_id = p_shop and d.active and d.unit = x.unit and lower(btrim(d.name)) = lower(btrim(x.name))
                            limit 1) m on true), '[]'::jsonb),
    'dest_ingredients', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name, 'unit', d.unit) order by d.name)
                                    from ingredients d where d.shop_id = p_shop and d.active), '[]'::jsonb),
    'topping_count', (select count(*) from menu_item_toppings x where x.item_id = p_item and x.active),
    'option_group_count', (select count(*) from menu_option_groups g where g.item_id = p_item and g.active));
end $$;

-- Thay thế hàm nội bộ ở 05: thêm ánh xạ nguyên liệu tay, sao chép topping/tùy chọn.
-- Size có nguyên liệu chưa khớp thì KHÔNG tạo công thức cho size đó (vốn/lãi "chưa xác định", chủ soạn công thức sau),
-- để không có công thức thiếu nguyên liệu làm sai kho và vốn.
drop function if exists _menu_copy_item(uuid, uuid, text);
create or replace function _menu_copy_item(p_item uuid, p_to_shop uuid, p_name text,
                                           p_mapping jsonb default '{}', p_copy_toppings boolean default false, p_copy_options boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_from uuid; v_src menu_items%rowtype; v_new uuid; v_cat text; v_s record; v_size uuid; v_ver uuid;
  v_lines integer := 0; v_skipped text[] := '{}'; v_l record; v_ing uuid; v_map uuid; v_ok boolean; v_resolved jsonb;
  v_t record; v_tid uuid; v_tskip text[] := '{}'; v_g record; v_gid uuid; v_c record; v_cing uuid; v_copied_t integer := 0; v_copied_g integer := 0;
begin
  select * into v_src from menu_items where id = p_item;
  v_from := v_src.shop_id;
  p_mapping := coalesce(p_mapping, '{}');
  if exists (select 1 from menu_items where shop_id = p_to_shop and lower(btrim(name)) = lower(btrim(p_name))) then
    raise exception 'MENU_NAME_DUPLICATE';
  end if;
  v_cat := v_src.group_name;
  if v_cat is not null and not exists (select 1 from menu_categories where shop_id = p_to_shop and lower(btrim(name)) = lower(btrim(v_cat))) then
    insert into menu_categories (shop_id, name, sort_order)
    values (p_to_shop, v_cat, coalesce((select max(sort_order) from menu_categories where shop_id = p_to_shop), 0) + 1);
  end if;
  insert into menu_items (shop_id, name, group_name, active, is_draft, description, image_path, topping_max_kinds, topping_max_portions)
  values (p_to_shop, btrim(p_name), v_cat, false, true, v_src.description,
          case when p_to_shop = v_from then v_src.image_path end,
          v_src.topping_max_kinds, v_src.topping_max_portions)
  returning id into v_new;

  -- Đối chiếu từng nguyên liệu nguồn -> nguyên liệu quán nhận (ánh xạ tay, rồi cùng tên + đơn vị)
  for v_l in select distinct rl.ingredient_id, i.name, i.unit
               from menu_sizes ms join recipe_lines rl on rl.size_id = ms.id join ingredients i on i.id = rl.ingredient_id
              where ms.item_id = p_item and ms.active loop
    if p_to_shop = v_from then v_ing := v_l.ingredient_id;
    else
      v_ing := null;
      v_map := nullif(p_mapping->>(v_l.ingredient_id::text), '')::uuid;
      if v_map is not null then
        select id into v_ing from ingredients where id = v_map and shop_id = p_to_shop and active;
        if v_ing is null then raise exception 'INGREDIENT_NOT_FOUND'; end if;
        if (select unit from ingredients where id = v_ing) <> v_l.unit then raise exception 'INGREDIENT_UNIT_MISMATCH'; end if;
      else
        select id into v_ing from ingredients
         where shop_id = p_to_shop and active and unit = v_l.unit and lower(btrim(name)) = lower(btrim(v_l.name)) limit 1;
      end if;
    end if;
    v_resolved := coalesce(v_resolved, '{}') || jsonb_build_object(v_l.ingredient_id::text, v_ing);
  end loop;
  v_resolved := coalesce(v_resolved, '{}');

  for v_s in select * from menu_sizes where item_id = p_item and active order by price, size_name loop
    insert into menu_sizes (shop_id, item_id, size_name, price, active)
    values (p_to_shop, v_new, v_s.size_name, v_s.price, true) returning id into v_size;
    v_ok := true;
    for v_l in select rl.ingredient_id, i.name from recipe_lines rl join ingredients i on i.id = rl.ingredient_id where rl.size_id = v_s.id loop
      if nullif(v_resolved->>(v_l.ingredient_id::text), '') is null then
        v_ok := false;
        if not (v_l.name = any (v_skipped)) then v_skipped := array_append(v_skipped, v_l.name); end if;
      end if;
    end loop;
    if not v_ok or not exists (select 1 from recipe_lines where size_id = v_s.id) then continue; end if;
    insert into recipe_versions (shop_id, size_id, version_no, status, effective_from, applied_at, created_by)
    values (p_to_shop, v_size, 1, 'active', now(), now(), app_staff_id()) returning id into v_ver;
    for v_l in select rl.ingredient_id, rl.qty from recipe_lines rl where rl.size_id = v_s.id loop
      v_ing := (v_resolved->>(v_l.ingredient_id::text))::uuid;
      insert into recipe_version_lines (version_id, ingredient_id, qty) values (v_ver, v_ing, v_l.qty);
      perform set_config('fore.recipe_apply', 'on', true);
      insert into recipe_lines (shop_id, size_id, ingredient_id, qty) values (p_to_shop, v_size, v_ing, v_l.qty);
      perform set_config('fore.recipe_apply', 'off', true);
      v_lines := v_lines + 1;
    end loop;
  end loop;

  if p_copy_toppings then
    for v_t in select t.* from menu_item_toppings x join menu_toppings t on t.id = x.topping_id where x.item_id = p_item and x.active loop
      if p_to_shop = v_from then v_tid := v_t.id;
      else select id into v_tid from menu_toppings where shop_id = p_to_shop and lower(btrim(name)) = lower(btrim(v_t.name)) limit 1;
      end if;
      if v_tid is null then v_tskip := array_append(v_tskip, v_t.name); continue; end if;
      insert into menu_item_toppings (item_id, topping_id, shop_id, active) values (v_new, v_tid, p_to_shop, true);
      v_copied_t := v_copied_t + 1;
    end loop;
  end if;

  if p_copy_options then
    for v_g in select * from menu_option_groups where item_id = p_item and active order by sort_order loop
      insert into menu_option_groups (shop_id, item_id, name, required, sort_order) values (p_to_shop, v_new, v_g.name, v_g.required, v_g.sort_order)
      returning id into v_gid;
      for v_c in select * from menu_option_choices where group_id = v_g.id and active order by sort_order loop
        v_cing := null;
        if v_c.ingredient_id is not null then
          if p_to_shop = v_from then v_cing := v_c.ingredient_id;
          else v_cing := nullif(v_resolved->>(v_c.ingredient_id::text), '')::uuid;
          end if;
        end if;
        -- định lượng riêng chỉ giữ khi tìm được nguyên liệu tương ứng; nếu không thì chỉ còn là chỉ dẫn
        insert into menu_option_choices (group_id, shop_id, name, is_default, price_delta, ingredient_id, qty, sort_order)
        values (v_gid, p_to_shop, v_c.name, v_c.is_default, v_c.price_delta, v_cing, case when v_cing is null then null else v_c.qty end, v_c.sort_order);
      end loop;
      v_copied_g := v_copied_g + 1;
    end loop;
  end if;

  return jsonb_build_object('item_id', v_new, 'copied_lines', v_lines, 'skipped_ingredients', to_jsonb(v_skipped),
                            'copied_toppings', v_copied_t, 'skipped_toppings', to_jsonb(v_tskip), 'copied_option_groups', v_copied_g);
end $$;

-- Hàm 3 tham số ở 05 vẫn dùng được (không ánh xạ tay, không chép topping/tùy chọn).
create or replace function menu_item_copy_to_shop(p_item uuid, p_shop uuid, p_new_name text, p_mapping jsonb, p_copy_toppings boolean, p_copy_options boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_src menu_items%rowtype; v_r jsonb; v_name text;
begin
  perform _require_owner();
  select * into v_src from menu_items where id = p_item and shop_id = app_shop_id();
  if not found then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if p_shop is null or (p_shop <> app_shop_id() and not exists (
       select 1 from staff s where s.auth_user_id = auth.uid() and s.active and s.role = 'owner' and s.shop_id = p_shop)) then
    raise exception 'OWNER_ONLY';
  end if;
  v_name := coalesce(nullif(btrim(coalesce(p_new_name, '')), ''), v_src.name);
  v_r := _menu_copy_item(p_item, p_shop, v_name, p_mapping, coalesce(p_copy_toppings, false), coalesce(p_copy_options, false));
  insert into menu_events (shop_id, item_id, kind, summary, detail, actor)
  values (p_shop, (v_r->>'item_id')::uuid, 'copy',
          case when p_shop = app_shop_id() then 'Tạo bản sao từ "' || v_src.name || '" (bản nháp)' else 'Sao chép từ quán khác (bản nháp)' end, v_r,
          (select s.id from staff s where s.auth_user_id = auth.uid() and s.shop_id = p_shop and s.active limit 1));
  if p_shop <> app_shop_id() then perform _menu_event(p_item, null, 'copy', 'Sao chép sang quán khác'); end if;
  return v_r;
end $$;

-- Hàm 3 tham số (05) gọi hàm nội bộ cũ đã bị thay thế ở trên: viết lại cho dùng hàm mới.
create or replace function menu_item_copy(p_item uuid, p_new_name text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_name text := btrim(coalesce(p_new_name, ''));
begin
  perform _require_owner();
  if not exists (select 1 from menu_items where id = p_item and shop_id = v_shop) then raise exception 'MENU_ITEM_NOT_FOUND'; end if;
  if v_name = '' then raise exception 'MENU_NAME_REQUIRED'; end if;
  return menu_item_copy_to_shop(p_item, v_shop, v_name, '{}', false, false);
end $$;

create or replace function menu_item_copy_to_shop(p_item uuid, p_shop uuid, p_new_name text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  if p_shop is not distinct from app_shop_id() then raise exception 'OWNER_ONLY'; end if;   -- cùng quán: dùng menu_item_copy
  return menu_item_copy_to_shop(p_item, p_shop, p_new_name, '{}'::jsonb, false, false);
end $$;

-- ---------- 5) Quyền gọi ----------
revoke all on function
  menu_toppings_list(), menu_topping_save(uuid, text, integer, uuid, integer, boolean), menu_item_extras(uuid),
  menu_item_toppings_save(uuid, uuid[], integer, integer), menu_item_options_save(uuid, jsonb),
  menu_copy_preview(uuid, uuid, text), menu_item_copy_to_shop(uuid, uuid, text, jsonb, boolean, boolean),
  menu_item_copy_to_shop(uuid, uuid, text), menu_item_copy(uuid, text)
  from public, anon;
grant execute on function
  menu_toppings_list(), menu_topping_save(uuid, text, integer, uuid, integer, boolean), menu_item_extras(uuid),
  menu_item_toppings_save(uuid, uuid[], integer, integer), menu_item_options_save(uuid, jsonb),
  menu_copy_preview(uuid, uuid, text), menu_item_copy_to_shop(uuid, uuid, text, jsonb, boolean, boolean),
  menu_item_copy_to_shop(uuid, uuid, text), menu_item_copy(uuid, text)
  to authenticated;
revoke all on function _menu_topping_json(uuid), _menu_copy_item(uuid, uuid, text, jsonb, boolean, boolean) from public, anon, authenticated;

-- >>> SOURCE: database/07_inventory.sql
-- Fore · 07_inventory.sql
-- Module KHO v2: nhóm nguyên liệu, nhà cung cấp, lô hàng + hạn dùng, phiếu nhập nhiều dòng,
-- giá nhập / giá bình quân, kiểm kê có duyệt, hao hụt theo lô, gợi ý nhập hàng, tổng quan kho.
-- Chạy SAU 06_menu_options.sql và TRƯỚC 08_settings.sql (một số hàm đọc quyền theo vai trò từ 08: _require_perm).
-- Chạy lại nhiều lần không hỏng (idempotent).
--
-- NGUYÊN TẮC (giữ đúng tinh thần các module trước):
--   · Sổ kho (stock_ledger) vẫn là nguồn sự thật duy nhất của tồn kho. Không có cột "tồn" để sửa tay.
--   · Tồn dự kiến = lần đếm gần nhất (stock_counts) + các dòng sổ kho sau đó (giống v_expected_stock),
--     nhưng nguyên liệu CHƯA TỪNG ĐẾM vẫn có tồn (= tổng sổ kho) để phiếu nhập đầu tiên hiện được.
--   · Nhân viên KHÔNG BAO GIỜ nhận số tồn hệ thống hay giá (đếm mù). Chỉ chủ xem.
--   · Mọi thay đổi tồn đều có phiếu và người ghi: PN-xxxx nhập, KK-xxxx kiểm kê, HH-xxxx hao hụt.
--   · Giá nhập MỚI khác giá BÌNH QUÂN: giá bình quân gia quyền cập nhật khi xác nhận phiếu nhập;
--     giá bán KHÔNG tự đổi.
--   · Mã tiền là số nguyên đồng; đơn giá lưu theo ĐƠN VỊ GỐC (ml, g, cái) → 50.000đ/lít = 50đ/ml.

-- ======================================================================
-- 1) Mở rộng bảng có sẵn
-- ======================================================================
alter table ingredients add column if not exists default_supplier_id uuid;
alter table ingredients add column if not exists storage_note text;
alter table ingredients add column if not exists last_purchase_cost numeric(14,4) check (last_purchase_cost is null or last_purchase_cost >= 0);
alter table ingredients add column if not exists last_purchase_at timestamptz;

-- Sổ kho thêm loại "adjust" (điều chỉnh sau kiểm kê được chủ duyệt) và cho phép ngoài ca
alter table stock_ledger drop constraint if exists stock_ledger_kind_check;
alter table stock_ledger add constraint stock_ledger_kind_check
  check (kind in ('purchase', 'sale', 'void_sale', 'waste', 'adjust'));
alter table stock_ledger alter column shift_id drop not null;

alter table waste_logs add column if not exists code text;
alter table waste_logs add column if not exists lot_id uuid;

-- ======================================================================
-- 2) Bảng mới
-- ======================================================================
create table if not exists inv_code_counters (
  shop_id  uuid not null references shops(id),
  prefix   text not null,
  day_key  text not null,
  n        integer not null default 0,
  primary key (shop_id, prefix, day_key)
);

create table if not exists ingredient_groups (
  id          uuid primary key default gen_random_uuid(),
  shop_id     uuid not null default app_shop_id() references shops(id),
  name        text not null check (char_length(btrim(name)) between 1 and 60),
  sort_order  integer not null default 0,
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  unique (shop_id, id)
);
create unique index if not exists ingredient_groups_name_uq on ingredient_groups (shop_id, lower(btrim(name)));

create table if not exists suppliers (
  id               uuid primary key default gen_random_uuid(),
  shop_id          uuid not null default app_shop_id() references shops(id),
  name             text not null check (char_length(btrim(name)) between 1 and 80),
  contact_name     text,
  phone            text,
  email            text,
  address          text,
  lead_days        integer not null default 1 check (lead_days between 0 and 30),
  delivery_window  text,                 -- "07:00–10:00"
  order_cutoff     text,                 -- "16:00" (giờ chốt đặt hàng trong ngày)
  note             text,
  active           boolean not null default true,
  created_at       timestamptz not null default now(),
  unique (shop_id, id)
);
create unique index if not exists suppliers_name_uq on suppliers (shop_id, lower(btrim(name)));

create table if not exists purchase_orders (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid not null default app_shop_id() references shops(id),
  code           text not null,
  supplier_id    uuid,
  status         text not null default 'draft' check (status in ('draft', 'confirmed', 'cancelled')),
  source         text not null default 'owner' check (source in ('owner', 'staff', 'suggestion')),
  note           text,
  vat_included   boolean not null default true,
  shipping_fee   integer not null default 0 check (shipping_fee >= 0),
  received_at    timestamptz,
  needs_pricing  boolean not null default false,   -- nhân viên nhận hàng, chủ chưa bổ sung giá
  total_amount   bigint,
  cancel_reason  text,
  created_by     uuid references staff(id),
  confirmed_by   uuid references staff(id),
  confirmed_at   timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (shop_id, id),
  unique (shop_id, code)
);
create index if not exists purchase_orders_status_idx on purchase_orders (shop_id, status, created_at desc);

create table if not exists purchase_order_lines (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid not null default app_shop_id() references shops(id),
  order_id       uuid not null references purchase_orders(id) on delete cascade,
  ingredient_id  uuid not null references ingredients(id),
  qty            integer not null check (qty > 0),                       -- đơn vị gốc
  unit_price     numeric(14,4) check (unit_price is null or unit_price >= 0),  -- đồng / đơn vị gốc
  lot_code       text,
  expiry_date    date,
  lot_id         uuid,
  created_at     timestamptz not null default now()
);
create index if not exists purchase_order_lines_order_idx on purchase_order_lines (order_id);

create table if not exists stock_lots (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid not null default app_shop_id() references shops(id),
  ingredient_id  uuid not null references ingredients(id),
  code           text not null,
  received_at    timestamptz not null,
  expiry_date    date,
  qty_received   integer not null check (qty_received > 0),
  unit_cost      numeric(14,4),
  order_line_id  uuid,
  created_at     timestamptz not null default now(),
  unique (shop_id, id)
);
create index if not exists stock_lots_ing_idx on stock_lots (ingredient_id, received_at desc);

create table if not exists ingredient_cost_events (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid not null default app_shop_id() references shops(id),
  ingredient_id  uuid not null references ingredients(id),
  at             timestamptz not null default now(),
  kind           text not null check (kind in ('purchase', 'manual')),
  price          numeric(14,4),        -- giá nhập của lần này (đồng / đơn vị gốc)
  avg_before     numeric(14,4),
  avg_after      numeric(14,4),
  qty            integer,
  order_id       uuid,
  created_by     uuid references staff(id)
);
create index if not exists ingredient_cost_events_ing_idx on ingredient_cost_events (ingredient_id, at desc);

create table if not exists stocktakes (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid not null default app_shop_id() references shops(id),
  code           text not null,
  status         text not null default 'draft' check (status in ('draft', 'submitted', 'recount', 'approved')),
  started_by     uuid not null references staff(id),
  started_at     timestamptz not null default now(),
  saved_at       timestamptz,
  submitted_at   timestamptz,
  reviewed_by    uuid references staff(id),
  reviewed_at    timestamptz,
  review_reason  text,
  review_note    text,
  unique (shop_id, id),
  unique (shop_id, code)
);
create unique index if not exists stocktakes_one_draft_uq on stocktakes (shop_id, started_by) where status in ('draft', 'recount');

create table if not exists stocktake_lines (
  id                 uuid primary key default gen_random_uuid(),
  shop_id            uuid not null default app_shop_id() references shops(id),
  stocktake_id       uuid not null references stocktakes(id) on delete cascade,
  ingredient_id      uuid not null references ingredients(id),
  counted_qty        integer check (counted_qty is null or counted_qty >= 0),
  counted_at         timestamptz,
  system_qty         integer,                 -- chụp lúc ĐẾM (st_save); không bao giờ trả cho nhân viên
  unit_cost          numeric(14,4),
  recount_requested  boolean not null default false,
  recount_prev_qty   integer,
  decision           text check (decision is null or decision in ('adjust', 'keep')),
  unique (stocktake_id, ingredient_id)
);

create table if not exists inventory_requests (
  id           uuid primary key default gen_random_uuid(),
  shop_id      uuid not null default app_shop_id() references shops(id),
  kind         text not null check (kind in ('waste', 'purchase')),
  ref_id       uuid not null,
  note         text not null check (char_length(btrim(note)) >= 3),
  status       text not null default 'open' check (status in ('open', 'resolved')),
  created_by   uuid references staff(id),
  created_at   timestamptz not null default now(),
  resolved_at  timestamptz
);

-- Dữ liệu cũ: dựng nhóm từ group_name hiện có; thêm loại hao hụt cho các quán đang chạy
insert into ingredient_groups (shop_id, name, sort_order)
select i.shop_id, i.group_name, row_number() over (partition by i.shop_id order by i.group_name)
  from (select distinct shop_id, btrim(group_name) as group_name
          from ingredients where group_name is not null and btrim(group_name) <> '') i
on conflict do nothing;

insert into waste_types (shop_id, code, label_vi, requires_note, sort_order)
select s.id, t.code, t.label, false, t.ord
  from shops s
  cross join (values ('spill', 'Đổ vỡ / rơi vãi', 5), ('calibration', 'Căn chỉnh máy', 6)) as t(code, label, ord)
on conflict do nothing;

-- Quán mới: có sẵn hai loại hao hụt bổ sung
create or replace function inv_seed_trg() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into waste_types (shop_id, code, label_vi, requires_note, sort_order) values
    (new.id, 'spill', 'Đổ vỡ / rơi vãi', false, 5),
    (new.id, 'calibration', 'Căn chỉnh máy', false, 6)
  on conflict do nothing;
  return new;
end $$;
drop trigger if exists shops_seed_inventory on shops;
create trigger shops_seed_inventory after insert on shops for each row execute function inv_seed_trg();

-- ======================================================================
-- 3) Hàm nội bộ (không cấp cho app)
-- ======================================================================
create or replace function _inv_code(p_prefix text) returns text
language plpgsql security definer set search_path = public as $$
declare v_shop uuid := app_shop_id(); v_day text := to_char(now() at time zone 'Asia/Ho_Chi_Minh', 'DDMM'); v_n integer;
begin
  insert into inv_code_counters (shop_id, prefix, day_key, n) values (v_shop, p_prefix, v_day, 1)
  on conflict (shop_id, prefix, day_key) do update set n = inv_code_counters.n + 1
  returning n into v_n;
  return p_prefix || '-' || v_day || case when v_n > 1 then '-' || v_n::text else '' end;
end $$;

-- Tồn của MỌI nguyên liệu trong một quán (lần đếm gần nhất + sổ kho sau đó)
create or replace function _inv_stock_all(p_shop uuid)
returns table (ingredient_id uuid, stock integer, last_count_at timestamptz)
language sql stable security definer set search_path = public as $$
  select i.id,
         (coalesce(c.counted_qty, 0) + coalesce((select sum(l.qty_delta) from stock_ledger l
                                                  where l.ingredient_id = i.id
                                                    and l.at > coalesce(c.counted_at, '-infinity'::timestamptz)), 0))::integer,
         c.counted_at
    from ingredients i
    left join lateral (select counted_qty, counted_at from stock_counts
                        where ingredient_id = i.id order by counted_at desc limit 1) c on true
   where i.shop_id = p_shop
$$;

create or replace function _inv_stock(p_ing uuid) returns integer
language sql stable security definer set search_path = public as $$
  select (coalesce(c.counted_qty, 0) + coalesce((select sum(l.qty_delta) from stock_ledger l
                                                  where l.ingredient_id = p_ing
                                                    and l.at > coalesce(c.counted_at, '-infinity'::timestamptz)), 0))::integer
    from (select 1) x
    left join lateral (select counted_qty, counted_at from stock_counts
                        where ingredient_id = p_ing order by counted_at desc limit 1) c on true
$$;

-- Mức dùng trung bình mỗi ngày (bán + hao hụt) trong p_days ngày gần nhất
create or replace function _inv_daily_use(p_shop uuid, p_days integer default 7)
returns table (ingredient_id uuid, per_day numeric)
language sql stable security definer set search_path = public as $$
  select l.ingredient_id, (-sum(l.qty_delta))::numeric / greatest(p_days, 1)
    from stock_ledger l
   where l.shop_id = p_shop and l.kind in ('sale', 'void_sale', 'waste')
     and l.at >= now() - make_interval(days => greatest(p_days, 1))
   group by l.ingredient_id
  having -sum(l.qty_delta) > 0
$$;

-- Lô còn lại: tồn được "xếp" vào các lô mới nhất trước (lô cũ dùng trước)
create or replace function _inv_lots_all(p_shop uuid)
returns table (lot_id uuid, ingredient_id uuid, code text, received_at timestamptz, expiry_date date,
               qty_received integer, qty_remaining integer, unit_cost numeric)
language sql stable security definer set search_path = public as $$
  with st as (select s.ingredient_id as iid, greatest(s.stock, 0) as stock from _inv_stock_all(p_shop) s),
  l as (
    select sl.id, sl.ingredient_id as iid, sl.code, sl.received_at, sl.expiry_date, sl.qty_received, sl.unit_cost,
           sum(sl.qty_received) over (partition by sl.ingredient_id order by sl.received_at desc, sl.id desc) as cum
      from stock_lots sl where sl.shop_id = p_shop)
  select l.id, l.iid, l.code, l.received_at, l.expiry_date, l.qty_received,
         greatest(least(l.qty_received::bigint, st.stock - (l.cum - l.qty_received)), 0)::integer,
         l.unit_cost
    from l join st on st.iid = l.iid
$$;

create or replace function _vn_day(p_ts timestamptz) returns date
language sql immutable as $$ select (p_ts at time zone 'Asia/Ho_Chi_Minh')::date $$;

create or replace function _inv_status(p_stock integer, p_min integer) returns text
language sql immutable as $$
  select case when p_stock <= 0 then 'out'
              when p_min > 0 and p_stock <= p_min then 'low'
              else 'ok' end
$$;

-- ======================================================================
-- 4) Nhóm nguyên liệu
-- ======================================================================
create or replace function inv_groups() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid;
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', g.id, 'name', g.name, 'active', g.active,
             'ingredient_count', (select count(*) from ingredients i
                                   where i.shop_id = v_shop and i.active and lower(btrim(i.group_name)) = lower(btrim(g.name))),
             'menu_item_count', (select count(distinct ms.item_id) from ingredients i
                                   join recipe_lines rl on rl.ingredient_id = i.id
                                   join menu_sizes ms on ms.id = rl.size_id and ms.active
                                  where i.shop_id = v_shop and lower(btrim(i.group_name)) = lower(btrim(g.name))))
           order by g.active desc, g.sort_order, g.name)
      from ingredient_groups g where g.shop_id = v_shop), '[]'::jsonb);
end $$;

create or replace function inv_group_save(p_id uuid, p_name text) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_shop uuid; v_id uuid := p_id; v_old text; v_name text := btrim(coalesce(p_name, ''));
begin
  perform _require_owner(); v_shop := app_shop_id();
  if v_name = '' then raise exception 'NAME_REQUIRED'; end if;
  if v_id is null then
    insert into ingredient_groups (name, sort_order)
    values (v_name, coalesce((select max(sort_order) + 1 from ingredient_groups where shop_id = v_shop), 1))
    returning id into v_id;
  else
    select name into v_old from ingredient_groups where id = v_id and shop_id = v_shop;
    if not found then raise exception 'NOT_FOUND'; end if;
    update ingredient_groups set name = v_name where id = v_id;
    update ingredients set group_name = v_name
     where shop_id = v_shop and lower(btrim(group_name)) = lower(btrim(v_old));
  end if;
  return v_id;
exception when unique_violation then raise exception 'NAME_EXISTS';
end $$;

create or replace function inv_group_set_active(p_id uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public as $$
declare v_shop uuid; v_name text;
begin
  perform _require_owner(); v_shop := app_shop_id();
  select name into v_name from ingredient_groups where id = p_id and shop_id = v_shop;
  if not found then raise exception 'NOT_FOUND'; end if;
  if not p_active and exists (select 1 from ingredients i
                               where i.shop_id = v_shop and i.active and lower(btrim(i.group_name)) = lower(btrim(v_name))) then
    raise exception 'GROUP_NOT_EMPTY';
  end if;
  update ingredient_groups set active = p_active where id = p_id;
end $$;

-- ======================================================================
-- 5) Nhà cung cấp
-- ======================================================================
create or replace function sup_save(p_id uuid, p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_shop uuid; v_id uuid := p_id; v_name text := btrim(coalesce(p->>'name', ''));
  v_lead integer := coalesce(nullif(p->>'lead_days', '')::integer, 1);
begin
  perform _require_owner(); v_shop := app_shop_id();
  if v_name = '' then raise exception 'NAME_REQUIRED'; end if;
  if v_lead < 0 or v_lead > 30 then raise exception 'LEAD_DAYS_INVALID'; end if;
  if coalesce(p->>'email', '') <> '' and (p->>'email') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'EMAIL_INVALID'; end if;
  if v_id is null then
    insert into suppliers (name, contact_name, phone, email, address, lead_days, delivery_window, order_cutoff, note)
    values (v_name, nullif(btrim(p->>'contact_name'), ''), nullif(btrim(p->>'phone'), ''), nullif(lower(btrim(p->>'email')), ''),
            nullif(btrim(p->>'address'), ''), v_lead, nullif(btrim(p->>'delivery_window'), ''),
            nullif(btrim(p->>'order_cutoff'), ''), nullif(btrim(p->>'note'), ''))
    returning id into v_id;
  else
    update suppliers set name = v_name, contact_name = nullif(btrim(p->>'contact_name'), ''),
           phone = nullif(btrim(p->>'phone'), ''), email = nullif(lower(btrim(p->>'email')), ''),
           address = nullif(btrim(p->>'address'), ''), lead_days = v_lead,
           delivery_window = nullif(btrim(p->>'delivery_window'), ''),
           order_cutoff = nullif(btrim(p->>'order_cutoff'), ''), note = nullif(btrim(p->>'note'), '')
     where id = v_id and shop_id = v_shop;
    if not found then raise exception 'NOT_FOUND'; end if;
  end if;
  return v_id;
exception when unique_violation then raise exception 'NAME_EXISTS';
end $$;

create or replace function sup_set_active(p_id uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform _require_owner();
  update suppliers set active = p_active where id = p_id and shop_id = app_shop_id();
  if not found then raise exception 'NOT_FOUND'; end if;
end $$;

-- Danh sách nhà cung cấp (chủ): kèm mặt hàng và lần nhập gần nhất
create or replace function sup_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid;
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', s.id, 'name', s.name, 'contact_name', s.contact_name, 'phone', s.phone, 'active', s.active,
      'lead_days', s.lead_days,
      'items', coalesce((select jsonb_agg(i.name order by i.name) from ingredients i
                          where i.shop_id = v_shop and i.active and i.default_supplier_id = s.id), '[]'::jsonb),
      'last_order_at', (select max(po.received_at) from purchase_orders po
                         where po.shop_id = v_shop and po.supplier_id = s.id and po.status = 'confirmed'))
      order by s.active desc, s.name)
    from suppliers s where s.shop_id = v_shop), '[]'::jsonb);
end $$;

-- Danh sách chọn nhà cung cấp cho cả nhân viên (chỉ tên)
create or replace function sup_options() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_staff();
  return coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name) order by s.name)
                     from suppliers s where s.shop_id = app_shop_id() and s.active), '[]'::jsonb);
end $$;

create or replace function sup_detail(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; s suppliers;
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  select * into s from suppliers where id = p_id and shop_id = v_shop;
  if not found then raise exception 'NOT_FOUND'; end if;
  return jsonb_build_object(
    'id', s.id, 'name', s.name, 'contact_name', s.contact_name, 'phone', s.phone, 'email', s.email,
    'address', s.address, 'lead_days', s.lead_days, 'delivery_window', s.delivery_window,
    'order_cutoff', s.order_cutoff, 'note', s.note, 'active', s.active, 'created_at', s.created_at,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'ingredient_id', i.id, 'name', i.name, 'unit', i.unit,
               'last_price', i.last_purchase_cost, 'last_at', i.last_purchase_at) order by i.name)
        from ingredients i where i.shop_id = v_shop and i.active and i.default_supplier_id = s.id), '[]'::jsonb),
    'orders', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', po.id, 'code', po.code, 'received_at', po.received_at, 'total_amount', po.total_amount,
               'line_count', (select count(*) from purchase_order_lines l where l.order_id = po.id),
               'needs_pricing', po.needs_pricing) order by po.received_at desc)
        from (select * from purchase_orders x where x.shop_id = v_shop and x.supplier_id = s.id and x.status = 'confirmed'
               order by x.received_at desc limit 10) po), '[]'::jsonb),
    'draft_count', (select count(*) from purchase_orders x where x.shop_id = v_shop and x.supplier_id = s.id and x.status = 'draft'));
end $$;

-- ======================================================================
-- 6) Nguyên liệu: lưu, danh mục, hồ sơ, lịch sử
-- ======================================================================
create or replace function inv_ingredient_save(p_id uuid, p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_shop uuid; v_id uuid := p_id; v_name text := btrim(coalesce(p->>'name', ''));
  v_unit text := p->>'unit'; v_group text; v_gid uuid := nullif(p->>'group_id', '')::uuid;
  v_sup uuid := nullif(p->>'default_supplier_id', '')::uuid;
  v_min integer := coalesce(nullif(p->>'min_stock_qty', '')::integer, 0);
  v_imp text := coalesce(nullif(p->>'importance', ''), 'normal');
  v_old ingredients;
begin
  perform _require_owner(); v_shop := app_shop_id();
  if v_name = '' then raise exception 'NAME_REQUIRED'; end if;
  if v_min < 0 then raise exception 'QTY_INVALID'; end if;
  if v_imp not in ('important', 'normal') then raise exception 'IMPORTANCE_INVALID'; end if;
  if v_gid is not null then
    select name into v_group from ingredient_groups where id = v_gid and shop_id = v_shop and active;
    if not found then raise exception 'GROUP_REQUIRED'; end if;
  end if;
  if v_sup is not null and not exists (select 1 from suppliers where id = v_sup and shop_id = v_shop) then
    raise exception 'NOT_FOUND';
  end if;
  if v_id is null then
    if v_unit is null or v_unit not in ('ml', 'g', 'piece') then raise exception 'UNIT_INVALID'; end if;
    if v_group is null then raise exception 'GROUP_REQUIRED'; end if;
    insert into ingredients (name, group_name, unit, importance, min_stock_qty, default_supplier_id, storage_note)
    values (v_name, v_group, v_unit, v_imp, v_min, v_sup, nullif(btrim(p->>'storage_note'), ''))
    returning id into v_id;
    perform _audit('ingredient_create', 'ingredient', v_id, jsonb_build_object('name', v_name));
  else
    select * into v_old from ingredients where id = v_id and shop_id = v_shop;
    if not found then raise exception 'NOT_FOUND'; end if;
    if v_unit is not null and v_unit <> v_old.unit then
      if exists (select 1 from stock_ledger where ingredient_id = v_id) or exists (select 1 from recipe_lines where ingredient_id = v_id) then
        raise exception 'UNIT_LOCKED';
      end if;
    else
      v_unit := v_old.unit;
    end if;
    update ingredients set name = v_name, unit = v_unit, group_name = coalesce(v_group, group_name),
           importance = v_imp, min_stock_qty = v_min, default_supplier_id = v_sup,
           storage_note = nullif(btrim(p->>'storage_note'), '')
     where id = v_id;
    perform _audit('ingredient_update', 'ingredient', v_id, jsonb_build_object('name', v_name));
  end if;
  return v_id;
exception when unique_violation then raise exception 'NAME_EXISTS';
end $$;

-- Ngừng dùng: không xóa; chỉ được khi tồn = 0 và không còn trong công thức đang dùng
create or replace function inv_ingredient_set_active(p_id uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public as $$
declare v_shop uuid;
begin
  perform _require_owner(); v_shop := app_shop_id();
  if not exists (select 1 from ingredients where id = p_id and shop_id = v_shop) then raise exception 'NOT_FOUND'; end if;
  if not p_active then
    if exists (select 1 from recipe_lines rl join menu_sizes ms on ms.id = rl.size_id and ms.active
                join menu_items mi on mi.id = ms.item_id and mi.active
               where rl.ingredient_id = p_id) then
      raise exception 'INGREDIENT_IN_RECIPE';
    end if;
    if _inv_stock(p_id) > 0 then raise exception 'STOCK_NOT_EMPTY'; end if;
  end if;
  update ingredients set active = p_active where id = p_id;
  perform _audit('ingredient_set_active', 'ingredient', p_id, jsonb_build_object('active', p_active));
end $$;

create or replace function inv_catalog(p_group text default null, p_search text default null, p_include_inactive boolean default false)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; v_q text := lower(btrim(coalesce(p_search, '')));
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  return coalesce((
    with st as (select * from _inv_stock_all(v_shop)),
         us as (select * from _inv_daily_use(v_shop, 7))
    select jsonb_agg(jsonb_build_object(
             'id', i.id, 'name', i.name, 'group_name', i.group_name, 'unit', i.unit, 'active', i.active,
             'stock', st.stock, 'unit_cost', i.unit_cost,
             'value', case when i.unit_cost is null then null else round(greatest(st.stock, 0) * i.unit_cost)::bigint end,
             'min_stock_qty', i.min_stock_qty,
             'status', _inv_status(st.stock, i.min_stock_qty),
             'days_left', case when us.per_day > 0 then round(greatest(st.stock, 0) / us.per_day, 1) end,
             'default_supplier_id', i.default_supplier_id,
             'supplier_name', (select s.name from suppliers s where s.id = i.default_supplier_id),
             'menu_item_count', (select count(distinct ms.item_id) from recipe_lines rl
                                  join menu_sizes ms on ms.id = rl.size_id and ms.active
                                 where rl.ingredient_id = i.id))
           order by i.active desc, (_inv_status(st.stock, i.min_stock_qty) = 'ok'), i.group_name nulls last, i.name)
      from ingredients i
      join st on st.ingredient_id = i.id
      left join us on us.ingredient_id = i.id
     where i.shop_id = v_shop and (i.active or p_include_inactive)
       and (p_group is null or lower(btrim(i.group_name)) = lower(btrim(p_group)))
       and (v_q = '' or lower(i.name) like '%' || v_q || '%')
  ), '[]'::jsonb);
end $$;

create or replace function inv_ingredient_profile(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; i ingredients; v_stock integer; v_use numeric; v_sup text;
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  select * into i from ingredients where id = p_id and shop_id = v_shop;
  if not found then raise exception 'NOT_FOUND'; end if;
  select s.stock into v_stock from _inv_stock_all(v_shop) s where s.ingredient_id = p_id;
  select u.per_day into v_use from _inv_daily_use(v_shop, 7) u where u.ingredient_id = p_id;
  select s.name into v_sup from suppliers s where s.id = i.default_supplier_id;
  return jsonb_build_object(
    'id', i.id, 'name', i.name, 'group_name', i.group_name, 'unit', i.unit, 'importance', i.importance,
    'active', i.active, 'storage_note', i.storage_note,
    'stock', v_stock, 'stock_at', now(),
    'last_count_at', (select max(c.counted_at) from stock_counts c where c.ingredient_id = p_id),
    'unit_cost', i.unit_cost, 'last_purchase_cost', i.last_purchase_cost, 'last_purchase_at', i.last_purchase_at,
    'value', case when i.unit_cost is null then null else round(greatest(v_stock, 0) * i.unit_cost)::bigint end,
    'min_stock_qty', i.min_stock_qty,
    'status', _inv_status(v_stock, i.min_stock_qty),
    'per_day', round(v_use, 2),
    'days_left', case when v_use > 0 then round(greatest(v_stock, 0) / v_use, 1) end,
    'default_supplier_id', i.default_supplier_id, 'supplier_name', v_sup,
    'supplier_lead_days', (select s.lead_days from suppliers s where s.id = i.default_supplier_id),
    'lots', coalesce((select jsonb_agg(jsonb_build_object(
                 'id', l.lot_id, 'code', l.code, 'received_at', l.received_at, 'expiry_date', l.expiry_date,
                 'qty_received', l.qty_received, 'qty_remaining', l.qty_remaining, 'unit_cost', l.unit_cost)
               order by l.expiry_date nulls last, l.received_at)
               from _inv_lots_all(v_shop) l where l.ingredient_id = p_id and l.qty_remaining > 0), '[]'::jsonb),
    'used_in', coalesce((select jsonb_agg(jsonb_build_object(
                 'item_name', mi.name, 'size_name', ms.size_name, 'qty', rl.qty) order by mi.name, ms.size_name)
               from recipe_lines rl join menu_sizes ms on ms.id = rl.size_id and ms.active
               join menu_items mi on mi.id = ms.item_id and mi.active
              where rl.ingredient_id = p_id), '[]'::jsonb));
end $$;

-- Sổ biến động + lịch sử giá nhập của một nguyên liệu
create or replace function inv_ingredient_history(p_id uuid, p_kind text default null, p_limit integer default 40)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; v_lim integer := least(greatest(coalesce(p_limit, 40), 1), 200);
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  if not exists (select 1 from ingredients where id = p_id and shop_id = v_shop) then raise exception 'NOT_FOUND'; end if;
  if p_kind is not null and p_kind not in ('purchase', 'waste', 'adjust', 'sale') then raise exception 'KIND_INVALID'; end if;
  return jsonb_build_object(
    'movements', coalesce((
      select jsonb_agg(m order by (m->>'at') desc) from (
        select jsonb_build_object(
                 'at', x.at, 'kind', x.kind, 'qty_delta', x.qty_delta, 'ref_code', x.ref_code,
                 'actor_name', x.actor_name, 'note', x.note) as m
          from (
            -- nhập / hao hụt / điều chỉnh: từng dòng, có mã phiếu và người ghi
            select l.at, l.kind, l.qty_delta::bigint as qty_delta,
                   case l.kind
                     when 'purchase' then (select po.code from purchase_order_lines pl join purchase_orders po on po.id = pl.order_id where pl.id = l.ref_id)
                     when 'waste' then (select w.code from waste_logs w where w.id = l.ref_id)
                     when 'adjust' then (select k.code from stocktakes k where k.id = l.ref_id)
                   end as ref_code,
                   (select s.full_name from staff s where s.id = l.created_by) as actor_name,
                   l.note
              from stock_ledger l
             where l.ingredient_id = p_id and l.shop_id = v_shop and l.kind in ('purchase', 'waste', 'adjust')
               and (p_kind is null or p_kind = l.kind)
            union all
            -- bán theo công thức: gộp theo ngày để sổ không dài vô tận
            select max(l.at), 'sale', sum(l.qty_delta)::bigint, null, null, null
              from stock_ledger l
             where l.ingredient_id = p_id and l.shop_id = v_shop and l.kind in ('sale', 'void_sale')
               and (p_kind is null or p_kind = 'sale')
             group by _vn_day(l.at)
          ) x
         order by x.at desc limit v_lim) q), '[]'::jsonb),
    'price_events', coalesce((
      select jsonb_agg(jsonb_build_object(
               'at', e.at, 'kind', e.kind, 'price', e.price, 'avg_before', e.avg_before, 'avg_after', e.avg_after,
               'qty', e.qty, 'order_code', (select po.code from purchase_orders po where po.id = e.order_id),
               'actor_name', (select s.full_name from staff s where s.id = e.created_by)) order by e.at desc)
        from (select * from ingredient_cost_events where ingredient_id = p_id and shop_id = v_shop
               order by at desc limit 20) e), '[]'::jsonb));
end $$;

-- Danh sách chọn nguyên liệu cho phiếu nhập (nhân viên cũng dùng, KHÔNG có tồn/giá)
create or replace function inv_picker() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_staff();
  return coalesce((select jsonb_agg(jsonb_build_object(
            'id', i.id, 'name', i.name, 'unit', i.unit, 'group_name', i.group_name,
            'default_supplier_id', i.default_supplier_id) order by i.group_name nulls last, i.name)
         from ingredients i where i.shop_id = app_shop_id() and i.active), '[]'::jsonb);
end $$;

-- Lô còn dùng được của một nguyên liệu: nhân viên chỉ thấy mã lô + hạn dùng, KHÔNG thấy số lượng
create or replace function inv_lots_for_staff(p_ingredient uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid;
begin
  perform _require_staff(); v_shop := app_shop_id();
  return coalesce((select jsonb_agg(jsonb_build_object(
            'id', l.lot_id, 'code', l.code, 'expiry_date', l.expiry_date, 'received_at', l.received_at)
            order by l.expiry_date nulls last, l.received_at)
         from _inv_lots_all(v_shop) l where l.ingredient_id = p_ingredient and l.qty_remaining > 0), '[]'::jsonb);
end $$;

-- ======================================================================
-- 7) Phiếu nhập hàng (PN)
-- ======================================================================
-- Áp giá nhập vào giá bình quân gia quyền. p_stock_before = tồn TRƯỚC khi hàng này vào kho.
create or replace function _inv_apply_cost(p_ing uuid, p_price numeric, p_qty integer, p_stock_before integer,
                                            p_at timestamptz, p_order uuid, p_by uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_avg numeric; v_new numeric; v_before integer := greatest(coalesce(p_stock_before, 0), 0);
begin
  select unit_cost into v_avg from ingredients where id = p_ing;
  if v_avg is null or v_before = 0 then
    v_new := p_price;
  else
    v_new := (v_before * v_avg + p_qty * p_price) / (v_before + p_qty);
  end if;
  update ingredients set unit_cost = round(v_new, 2), unit_cost_updated_at = now(),
         last_purchase_cost = p_price,
         last_purchase_at = greatest(coalesce(last_purchase_at, p_at), p_at)
   where id = p_ing;
  insert into ingredient_cost_events (ingredient_id, at, kind, price, avg_before, avg_after, qty, order_id, created_by)
  values (p_ing, p_at, 'purchase', p_price, v_avg, round(v_new, 2), p_qty, p_order, p_by);
end $$;

create or replace function _po_json(p_id uuid, p_prices boolean) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare o purchase_orders;
begin
  select * into o from purchase_orders where id = p_id and shop_id = app_shop_id();
  if not found then raise exception 'NOT_FOUND'; end if;
  return jsonb_build_object(
    'id', o.id, 'code', o.code, 'status', o.status, 'source', o.source, 'note', o.note,
    'supplier_id', o.supplier_id, 'supplier_name', (select s.name from suppliers s where s.id = o.supplier_id),
    'vat_included', o.vat_included, 'received_at', o.received_at, 'created_at', o.created_at, 'updated_at', o.updated_at,
    'needs_pricing', o.needs_pricing, 'cancel_reason', o.cancel_reason,
    'created_by_name', (select s.full_name from staff s where s.id = o.created_by),
    'shipping_fee', case when p_prices then o.shipping_fee end,
    'total_amount', case when p_prices then o.total_amount end,
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
               'id', l.id, 'ingredient_id', l.ingredient_id, 'name', i.name, 'unit', i.unit, 'qty', l.qty,
               'unit_price', case when p_prices then l.unit_price end,
               'line_total', case when p_prices and l.unit_price is not null then round(l.qty * l.unit_price)::bigint end,
               'lot_code', coalesce(l.lot_code, (select sl.code from stock_lots sl where sl.id = l.lot_id)),
               'expiry_date', l.expiry_date,
               'last_price', case when p_prices then i.last_purchase_cost end)
             order by l.created_at, l.id)
             from purchase_order_lines l join ingredients i on i.id = l.ingredient_id
            where l.order_id = o.id), '[]'::jsonb));
end $$;

-- Ghi hàng vào kho: tạo lô, dòng sổ kho, cập nhật giá bình quân
create or replace function _po_apply(p_order uuid, p_by uuid) returns void
language plpgsql security definer set search_path = public as $$
declare o purchase_orders; l purchase_order_lines; v_lot uuid; v_code text; v_shift uuid; v_before integer; v_at timestamptz;
begin
  select * into o from purchase_orders where id = p_order;
  v_at := least(coalesce(o.received_at, now()), now());
  select s.id into v_shift from shifts s
   where s.shop_id = o.shop_id and s.opened_at <= v_at and (s.closed_at is null or s.closed_at >= v_at)
   order by s.opened_at desc limit 1;
  for l in select * from purchase_order_lines where order_id = p_order order by created_at, id loop
    v_before := _inv_stock(l.ingredient_id);
    v_code := coalesce(nullif(btrim(l.lot_code), ''), _inv_code('ST'));
    insert into stock_lots (ingredient_id, code, received_at, expiry_date, qty_received, unit_cost, order_line_id)
    values (l.ingredient_id, v_code, v_at, l.expiry_date, l.qty, l.unit_price, l.id)
    returning id into v_lot;
    update purchase_order_lines set lot_id = v_lot where id = l.id;
    insert into stock_ledger (shift_id, ingredient_id, kind, qty_delta, ref_id, created_by, at, note)
    values (v_shift, l.ingredient_id, 'purchase', l.qty, l.id, p_by, v_at, o.code);
    if l.unit_price is not null then
      perform _inv_apply_cost(l.ingredient_id, l.unit_price, l.qty, v_before, v_at, p_order, p_by);
    end if;
  end loop;
end $$;

create or replace function po_save(p_id uuid, p jsonb, p_confirm boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := _require_perm('inventory.record'); v_shop uuid := app_shop_id(); v_owner boolean := app_is_owner();
  o purchase_orders; v_id uuid := p_id; e jsonb; v_ing uuid; v_qty integer; v_price numeric; v_exp date;
  v_sup uuid := nullif(p->>'supplier_id', '')::uuid; v_n integer := 0; v_total numeric := 0;
  v_ship integer := coalesce(nullif(p->>'shipping_fee', '')::integer, 0);
  v_recv timestamptz := coalesce(nullif(p->>'received_at', '')::timestamptz, now());
  v_unpriced boolean := false;
begin
  if v_recv > now() + interval '5 minutes' then raise exception 'DATE_INVALID'; end if;
  if v_ship < 0 then raise exception 'AMOUNT_INVALID'; end if;
  if v_sup is not null and not exists (select 1 from suppliers where id = v_sup and shop_id = v_shop and active) then
    raise exception 'NOT_FOUND';
  end if;
  if not v_owner then v_ship := 0; end if;

  if v_id is null then
    insert into purchase_orders (code, supplier_id, source, created_by)
    values (_inv_code('PN'), v_sup, case when v_owner then 'owner' else 'staff' end, v_me)
    returning id into v_id;
  end if;
  select * into o from purchase_orders where id = v_id and shop_id = v_shop for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if o.status <> 'draft' then raise exception 'ORDER_NOT_DRAFT'; end if;
  if not v_owner and o.created_by is distinct from v_me then raise exception 'OWNER_ONLY'; end if;

  delete from purchase_order_lines where order_id = v_id;
  for e in select * from jsonb_array_elements(coalesce(p->'lines', '[]'::jsonb)) loop
    v_ing := (e->>'ingredient_id')::uuid;
    if not exists (select 1 from ingredients where id = v_ing and shop_id = v_shop and active) then raise exception 'NOT_FOUND'; end if;
    begin v_qty := (e->>'qty')::integer; exception when others then raise exception 'QTY_INVALID'; end;
    if v_qty is null or v_qty <= 0 or v_qty > 1000000000 then raise exception 'QTY_INVALID'; end if;
    v_price := case when v_owner then nullif(e->>'unit_price', '')::numeric end;
    if v_price is not null and v_price < 0 then raise exception 'AMOUNT_INVALID'; end if;
    v_exp := nullif(e->>'expiry_date', '')::date;
    insert into purchase_order_lines (order_id, ingredient_id, qty, unit_price, lot_code, expiry_date)
    values (v_id, v_ing, v_qty, v_price, nullif(btrim(e->>'lot_code'), ''), v_exp);
    v_n := v_n + 1;
    if v_price is null then v_unpriced := true; else v_total := v_total + v_qty * v_price; end if;
  end loop;

  update purchase_orders set supplier_id = v_sup, note = nullif(btrim(p->>'note'), ''),
         vat_included = coalesce((p->>'vat_included')::boolean, true), shipping_fee = v_ship, received_at = v_recv,
         total_amount = case when v_n > 0 and not v_unpriced then round(v_total)::bigint + v_ship end,
         updated_at = now()
   where id = v_id;

  if p_confirm then
    if v_sup is null then raise exception 'SUPPLIER_REQUIRED'; end if;
    if v_n = 0 then raise exception 'LINES_REQUIRED'; end if;
    if v_owner and v_unpriced then raise exception 'PRICE_REQUIRED'; end if;
    if not v_owner then perform _open_shift_id(); end if;   -- nhân viên chỉ nhận hàng trong ca đang mở
    update purchase_orders set status = 'confirmed', confirmed_by = v_me, confirmed_at = now(),
           needs_pricing = v_unpriced, received_at = case when v_owner then v_recv else now() end,
           updated_at = now()
     where id = v_id;
    perform _po_apply(v_id, v_me);
    perform _audit('po_confirm', 'purchase_order', v_id, jsonb_build_object('code', o.code, 'lines', v_n));
  end if;
  return _po_json(v_id, v_owner);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
  raise exception 'INPUT_INVALID';
end $$;

create or replace function po_cancel(p_id uuid, p_reason text default null) returns void
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_staff(); o purchase_orders;
begin
  select * into o from purchase_orders where id = p_id and shop_id = app_shop_id() for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if o.status <> 'draft' then raise exception 'ORDER_NOT_DRAFT'; end if;
  if not app_is_owner() and o.created_by is distinct from v_me then raise exception 'OWNER_ONLY'; end if;
  update purchase_orders set status = 'cancelled', cancel_reason = nullif(btrim(p_reason), ''), updated_at = now() where id = p_id;
end $$;

-- Chủ bổ sung giá cho phiếu nhân viên đã nhận hàng
create or replace function po_set_prices(p_id uuid, p_lines jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_owner(); o purchase_orders; e jsonb; l purchase_order_lines; v_price numeric; v_before integer;
  v_unpriced boolean; v_total numeric;
begin
  select * into o from purchase_orders where id = p_id and shop_id = app_shop_id() for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if o.status <> 'confirmed' or not o.needs_pricing then raise exception 'ORDER_NOT_PRICEABLE'; end if;
  for e in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_price := nullif(e->>'unit_price', '')::numeric;
    if v_price is null or v_price < 0 then raise exception 'AMOUNT_INVALID'; end if;
    select * into l from purchase_order_lines where id = (e->>'line_id')::uuid and order_id = p_id for update;
    if not found then raise exception 'NOT_FOUND'; end if;
    if l.unit_price is not null then continue; end if;
    update purchase_order_lines set unit_price = v_price where id = l.id;
    update stock_lots set unit_cost = v_price where id = l.lot_id;
    -- tồn trước khi lô này vào kho ≈ tồn hiện tại trừ lượng lô (không âm)
    v_before := greatest(_inv_stock(l.ingredient_id) - l.qty, 0);
    perform _inv_apply_cost(l.ingredient_id, v_price, l.qty, v_before, coalesce(o.received_at, now()), p_id, v_me);
  end loop;
  select bool_or(unit_price is null), sum(qty * coalesce(unit_price, 0)) into v_unpriced, v_total
    from purchase_order_lines where order_id = p_id;
  update purchase_orders set needs_pricing = coalesce(v_unpriced, false),
         total_amount = case when coalesce(v_unpriced, false) then null else round(v_total)::bigint + shipping_fee end,
         updated_at = now()
   where id = p_id;
  perform _audit('po_set_prices', 'purchase_order', p_id, jsonb_build_object('code', o.code));
  return _po_json(p_id, true);
end $$;

create or replace function po_detail(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_me uuid := _require_staff(); o purchase_orders;
begin
  select * into o from purchase_orders where id = p_id and shop_id = app_shop_id();
  if not found then raise exception 'NOT_FOUND'; end if;
  if not app_is_owner() and o.created_by is distinct from v_me then raise exception 'OWNER_ONLY'; end if;
  return _po_json(p_id, app_is_owner());
end $$;

-- Danh sách phiếu: chủ thấy hết; nhân viên chỉ thấy phiếu của mình (không có giá)
create or replace function po_list(p_status text default null, p_limit integer default 30) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_me uuid := _require_staff(); v_owner boolean := app_is_owner(); v_lim integer := least(greatest(coalesce(p_limit, 30), 1), 100);
begin
  if p_status is not null and p_status not in ('draft', 'confirmed', 'cancelled') then raise exception 'KIND_INVALID'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', o.id, 'code', o.code, 'status', o.status, 'source', o.source,
             'supplier_name', (select s.name from suppliers s where s.id = o.supplier_id),
             'received_at', o.received_at, 'updated_at', o.updated_at, 'needs_pricing', o.needs_pricing,
             'total_amount', case when v_owner then o.total_amount end,
             'line_count', (select count(*) from purchase_order_lines l where l.order_id = o.id))
           order by o.updated_at desc)
      from (select * from purchase_orders x
             where x.shop_id = app_shop_id() and (p_status is null or x.status = p_status)
               and (v_owner or x.created_by = v_me)
             order by x.updated_at desc limit v_lim) o), '[]'::jsonb);
end $$;

-- Tác động giá của một phiếu NHÁP: giá bình quân mới và giá vốn các size dùng nguyên liệu đó.
-- Giá bán không đổi: chỉ cho chủ thấy biên lợi nhuận nếu giữ nguyên giá bán.
create or replace function po_impact(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; o purchase_orders; v_items jsonb; v_sizes jsonb;
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  select * into o from purchase_orders where id = p_id and shop_id = v_shop;
  if not found then raise exception 'NOT_FOUND'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'ingredient_id', q.id, 'name', q.name, 'unit', q.unit, 'qty', q.qty, 'price', q.price,
           'stock_before', q.stock_before, 'stock_after', q.stock_before + q.qty,
           'avg_before', q.unit_cost, 'last_price', q.last_purchase_cost,
           'avg_after', round(case when q.unit_cost is null or q.stock_pos = 0 then q.price
                                   else (q.stock_pos * q.unit_cost + q.qty * q.price) / (q.stock_pos + q.qty) end, 2),
           'price_change_pct', case when q.last_purchase_cost > 0 then round((q.price - q.last_purchase_cost) / q.last_purchase_cost * 100, 1) end,
           'avg_change_pct', case when q.unit_cost > 0 and q.stock_pos > 0
                                  then round(((q.stock_pos * q.unit_cost + q.qty * q.price) / (q.stock_pos + q.qty) - q.unit_cost) / q.unit_cost * 100, 1) end)
           order by q.name), '[]'::jsonb)
    into v_items
    from (
      select i.id, i.name, i.unit, i.unit_cost, i.last_purchase_cost,
             sum(l.qty)::integer as qty, (sum(l.qty * l.unit_price) / sum(l.qty)) as price,
             _inv_stock(i.id) as stock_before,
             greatest(_inv_stock(i.id), 0) as stock_pos
        from purchase_order_lines l join ingredients i on i.id = l.ingredient_id
       where l.order_id = p_id and l.unit_price is not null
       group by i.id, i.name, i.unit, i.unit_cost, i.last_purchase_cost) q;

  select coalesce(jsonb_agg(jsonb_build_object(
           'size_id', z.sid, 'item_name', z.item_name, 'size_name', z.size_name, 'sell_price', z.price,
           'cost_before', z.cost_before, 'cost_after', z.cost_after) order by (z.cost_after - z.cost_before) desc nulls last), '[]'::jsonb)
    into v_sizes
    from (
      select ms.id as sid, mi.name as item_name, ms.size_name, ms.price,
             case when bool_and(i.unit_cost is not null) then round(sum(rl.qty * i.unit_cost))::integer end as cost_before,
             round(sum(rl.qty * coalesce((c.e->>'avg_after')::numeric, i.unit_cost)))::integer as cost_after
        from menu_sizes ms
        join menu_items mi on mi.id = ms.item_id and mi.active
        join recipe_lines rl on rl.size_id = ms.id
        join ingredients i on i.id = rl.ingredient_id
        left join lateral (select e from jsonb_array_elements(v_items) e where (e->>'ingredient_id')::uuid = i.id limit 1) c on true
       where ms.shop_id = v_shop and ms.active
       group by ms.id, mi.name, ms.size_name, ms.price
      having bool_or(c.e is not null) and bool_and(i.unit_cost is not null or c.e is not null)
    ) z;
  return jsonb_build_object('order_id', p_id, 'code', o.code, 'items', v_items, 'sizes', v_sizes);
end $$;

-- ======================================================================
-- 8) Gợi ý nhập hàng
-- ======================================================================
create or replace function po_suggestions() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; v_items jsonb;
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  with st as (select * from _inv_stock_all(v_shop)),
       us as (select * from _inv_daily_use(v_shop, 7)),
  base as (
    select i.id, i.name, i.unit, i.group_name, i.min_stock_qty, i.last_purchase_cost, i.default_supplier_id,
           greatest(st.stock, 0) as stock, coalesce(us.per_day, 0) as per_day,
           coalesce(s.lead_days, 1) as lead_days, s.name as supplier_name, s.order_cutoff
      from ingredients i
      join st on st.ingredient_id = i.id
      left join us on us.ingredient_id = i.id
      left join suppliers s on s.id = i.default_supplier_id and s.active
     where i.shop_id = v_shop and i.active),
  need as (
    select b.*,
           ceil(greatest(b.per_day * (b.lead_days + 4) - b.stock, b.min_stock_qty * 2 - b.stock, 0)) as raw_qty
      from base b
     where (b.min_stock_qty > 0 and b.stock <= b.min_stock_qty)
        or (b.per_day > 0 and b.stock / b.per_day < b.lead_days + 2))
  select coalesce(jsonb_agg(jsonb_build_object(
           'ingredient_id', n.id, 'name', n.name, 'unit', n.unit, 'stock', n.stock,
           'per_day', round(n.per_day, 1),
           'days_left', case when n.per_day > 0 then round(n.stock / n.per_day, 1) end,
           'suggested_qty', case when n.unit = 'piece' then n.raw_qty::integer else (ceil(n.raw_qty / 500.0) * 500)::integer end,
           'supplier_id', n.default_supplier_id, 'supplier_name', n.supplier_name,
           'lead_days', n.lead_days, 'order_cutoff', n.order_cutoff, 'last_price', n.last_purchase_cost)
           order by n.supplier_name nulls last, (case when n.per_day > 0 then n.stock / n.per_day end) nulls last, n.name), '[]'::jsonb)
    into v_items
    from need n where n.raw_qty > 0;
  return jsonb_build_object(
    'generated_at', now(), 'window_days', 7, 'items', v_items,
    'draft_codes', coalesce((select jsonb_agg(po.code order by po.created_at) from purchase_orders po
                              where po.shop_id = v_shop and po.status = 'draft'), '[]'::jsonb));
end $$;

-- Tạo phiếu NHÁP từ gợi ý (mỗi nhà cung cấp một phiếu). Không gửi đơn đi đâu cả.
create or replace function po_from_suggestions(p_items jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_owner(); v_shop uuid := app_shop_id(); g record; v_id uuid; v_out jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(coalesce(p_items, 'null'::jsonb)) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'LINES_REQUIRED'; end if;
  for g in
    select nullif(e->>'supplier_id', '')::uuid as sup, jsonb_agg(e) as items
      from jsonb_array_elements(p_items) e group by 1
  loop
    if g.sup is not null and not exists (select 1 from suppliers where id = g.sup and shop_id = v_shop) then raise exception 'NOT_FOUND'; end if;
    insert into purchase_orders (code, supplier_id, source, created_by, note)
    values (_inv_code('PN'), g.sup, 'suggestion', v_me, 'Tạo từ gợi ý nhập hàng')
    returning id into v_id;
    insert into purchase_order_lines (order_id, ingredient_id, qty, unit_price)
    select v_id, (x->>'ingredient_id')::uuid, (x->>'qty')::integer,
           (select i.last_purchase_cost from ingredients i where i.id = (x->>'ingredient_id')::uuid)
      from jsonb_array_elements(g.items) x
     where exists (select 1 from ingredients i where i.id = (x->>'ingredient_id')::uuid and i.shop_id = v_shop and i.active)
       and (x->>'qty')::integer > 0;
    v_out := v_out || jsonb_build_object('id', v_id, 'code', (select code from purchase_orders where id = v_id));
  end loop;
  return v_out;
exception when invalid_text_representation then raise exception 'QTY_INVALID';
end $$;

-- ======================================================================
-- 9) Kiểm kê có duyệt (KK)
-- ======================================================================
create or replace function st_start() returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_perm('inventory.record'); v_shop uuid := app_shop_id(); v_id uuid; v_code text;
begin
  select id, code into v_id, v_code from stocktakes
   where shop_id = v_shop and started_by = v_me and status in ('draft', 'recount') order by started_at desc limit 1;
  if found then return jsonb_build_object('id', v_id, 'code', v_code, 'resumed', true); end if;
  v_code := _inv_code('KK');
  insert into stocktakes (code, started_by) values (v_code, v_me) returning id into v_id;
  insert into stocktake_lines (stocktake_id, ingredient_id)
  select v_id, i.id from ingredients i where i.shop_id = v_shop and i.active;
  return jsonb_build_object('id', v_id, 'code', v_code, 'resumed', false);
end $$;

-- Phiếu đếm MÙ: không có số hệ thống, không có giá
create or replace function st_sheet(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_me uuid := _require_staff(); k stocktakes;
begin
  select * into k from stocktakes where id = p_id and shop_id = app_shop_id();
  if not found then raise exception 'NOT_FOUND'; end if;
  if not app_is_owner() and k.started_by <> v_me then raise exception 'OWNER_ONLY'; end if;
  return jsonb_build_object(
    'id', k.id, 'code', k.code, 'status', k.status, 'started_at', k.started_at, 'saved_at', k.saved_at,
    'submitted_at', k.submitted_at, 'review_note', case when k.status = 'recount' then k.review_note end,
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
               'ingredient_id', l.ingredient_id, 'name', i.name, 'unit', i.unit, 'group_name', i.group_name,
               'counted_qty', l.counted_qty, 'recount_requested', l.recount_requested,
               'editable', (k.status = 'draft' or (k.status = 'recount' and l.recount_requested)))
             order by i.group_name nulls last, i.name)
        from stocktake_lines l join ingredients i on i.id = l.ingredient_id
       where l.stocktake_id = k.id), '[]'::jsonb));
end $$;

create or replace function st_save(p_id uuid, p_lines jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_perm('inventory.record'); k stocktakes; e jsonb; v_qty integer; v_ing uuid; l stocktake_lines;
begin
  select * into k from stocktakes where id = p_id and shop_id = app_shop_id() for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if k.started_by <> v_me then raise exception 'OWNER_ONLY'; end if;
  if k.status not in ('draft', 'recount') then raise exception 'STOCKTAKE_LOCKED'; end if;
  for e in select * from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) loop
    v_ing := (e->>'ingredient_id')::uuid;
    v_qty := nullif(e->>'counted_qty', '')::integer;
    if v_qty is not null and (v_qty < 0 or v_qty > 1000000000) then raise exception 'QTY_INVALID'; end if;
    select * into l from stocktake_lines where stocktake_id = p_id and ingredient_id = v_ing for update;
    if not found then raise exception 'NOT_FOUND'; end if;
    if k.status = 'recount' and not l.recount_requested then continue; end if;
    -- Lưu nháp lại cùng số thì giữ nguyên thời điểm đếm và số hệ thống đã chụp
    if v_qty is not distinct from l.counted_qty and l.system_qty is not null then continue; end if;
    -- Chụp tồn hệ thống NGAY LÚC ĐẾM: hàng bán/nhập giữa lúc đếm và lúc gửi không tạo lệch giả
    update stocktake_lines set
           recount_prev_qty = case when k.status = 'recount' and recount_prev_qty is null then counted_qty else recount_prev_qty end,
           counted_qty = v_qty, counted_at = case when v_qty is null then null else now() end,
           system_qty = case when v_qty is null then null else _inv_stock(v_ing) end,
           unit_cost = case when v_qty is null then null else (select i.unit_cost from ingredients i where i.id = v_ing) end
     where id = l.id;
  end loop;
  update stocktakes set saved_at = now() where id = p_id;
exception when invalid_text_representation then raise exception 'QTY_INVALID';
end $$;

create or replace function st_submit(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_perm('inventory.record'); k stocktakes; l stocktake_lines; v_shop uuid := app_shop_id();
begin
  select * into k from stocktakes where id = p_id and shop_id = v_shop for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if k.started_by <> v_me then raise exception 'OWNER_ONLY'; end if;
  if k.status not in ('draft', 'recount') then raise exception 'STOCKTAKE_LOCKED'; end if;
  if exists (select 1 from stocktake_lines x where x.stocktake_id = p_id and x.counted_qty is null
                and (k.status = 'draft' or x.recount_requested)) then
    raise exception 'COUNT_INCOMPLETE';
  end if;
  -- số hệ thống đã chụp lúc đếm (st_save); dòng nào còn thiếu thì chụp bây giờ
  update stocktake_lines x set
         system_qty = coalesce(x.system_qty, _inv_stock(x.ingredient_id)),
         unit_cost = coalesce(x.unit_cost, (select i.unit_cost from ingredients i where i.id = x.ingredient_id)),
         recount_requested = false
   where x.stocktake_id = p_id and (k.status = 'draft' or x.recount_requested);
  update stocktakes set status = 'submitted', submitted_at = now(), saved_at = now() where id = p_id;
  return jsonb_build_object('id', p_id, 'code', k.code, 'status', 'submitted',
                            'line_count', (select count(*) from stocktake_lines where stocktake_id = p_id));
end $$;

-- Chủ: danh sách phiếu kiểm kê
create or replace function st_list(p_status text default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid;
begin
  perform _require_perm('inventory.approve'); v_shop := app_shop_id();
  if p_status is not null and p_status not in ('draft', 'submitted', 'recount', 'approved') then raise exception 'KIND_INVALID'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', k.id, 'code', k.code, 'status', k.status, 'submitted_at', k.submitted_at, 'reviewed_at', k.reviewed_at,
             'staff_name', (select s.full_name from staff s where s.id = k.started_by),
             'line_count', (select count(*) from stocktake_lines l where l.stocktake_id = k.id),
             'variance_lines', (select count(*) from stocktake_lines l where l.stocktake_id = k.id and l.system_qty is not null and l.counted_qty <> l.system_qty),
             'net_value', (select round(sum((l.counted_qty - l.system_qty) * coalesce(l.unit_cost, 0)))::bigint
                             from stocktake_lines l where l.stocktake_id = k.id and l.system_qty is not null))
           order by coalesce(k.submitted_at, k.started_at) desc)
      from (select * from stocktakes x where x.shop_id = v_shop and (p_status is null or x.status = p_status)
             order by coalesce(x.submitted_at, x.started_at) desc limit 30) k), '[]'::jsonb);
end $$;

-- Chủ: chi tiết một phiếu, có số hệ thống và chênh lệch
create or replace function st_detail(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; k stocktakes;
begin
  perform _require_perm('inventory.approve'); v_shop := app_shop_id();
  select * into k from stocktakes where id = p_id and shop_id = v_shop;
  if not found then raise exception 'NOT_FOUND'; end if;
  return jsonb_build_object(
    'id', k.id, 'code', k.code, 'status', k.status, 'started_at', k.started_at, 'submitted_at', k.submitted_at,
    'reviewed_at', k.reviewed_at, 'review_reason', k.review_reason, 'review_note', k.review_note,
    'staff_name', (select s.full_name from staff s where s.id = k.started_by),
    'reviewer_name', (select s.full_name from staff s where s.id = k.reviewed_by),
    'stock_value_now', coalesce((select round(sum(greatest(s.stock, 0) * i.unit_cost))::bigint
                                   from ingredients i join _inv_stock_all(v_shop) s on s.ingredient_id = i.id
                                  where i.shop_id = v_shop and i.active and i.unit_cost is not null), 0),
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
               'ingredient_id', l.ingredient_id, 'name', i.name, 'unit', i.unit, 'group_name', i.group_name,
               'counted_qty', l.counted_qty, 'system_qty', l.system_qty, 'unit_cost', l.unit_cost,
               'variance', case when l.system_qty is null then null else l.counted_qty - l.system_qty end,
               'variance_value', case when l.system_qty is null then null
                                      else round((l.counted_qty - l.system_qty) * coalesce(l.unit_cost, 0))::bigint end,
               'recount_prev_qty', l.recount_prev_qty, 'recount_requested', l.recount_requested, 'decision', l.decision,
               'counted_at', l.counted_at)
             order by abs(coalesce(l.counted_qty - l.system_qty, 0)) desc, i.name)
        from stocktake_lines l join ingredients i on i.id = l.ingredient_id
       where l.stocktake_id = k.id), '[]'::jsonb));
end $$;

create or replace function st_request_recount(p_id uuid, p_ingredients uuid[], p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare k stocktakes; v_n integer;
begin
  perform _require_perm('inventory.approve');
  select * into k from stocktakes where id = p_id and shop_id = app_shop_id() for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if k.status <> 'submitted' then raise exception 'STOCKTAKE_LOCKED'; end if;
  if p_ingredients is null or array_length(p_ingredients, 1) is null then raise exception 'LINES_REQUIRED'; end if;
  -- xóa số hệ thống cũ: lần đếm lại sẽ chụp số mới lúc đếm
  update stocktake_lines set recount_requested = true, system_qty = null, unit_cost = null
   where stocktake_id = p_id and ingredient_id = any (p_ingredients);
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'NOT_FOUND'; end if;
  update stocktakes set status = 'recount', review_note = nullif(btrim(p_note), '') where id = p_id;
  perform _audit('st_recount', 'stocktake', p_id, jsonb_build_object('code', k.code, 'lines', v_n));
end $$;

-- Duyệt: dòng nào chọn 'adjust' thì ghi 1 dòng điều chỉnh vào sổ kho (KHÔNG tạo hao hụt). Phải có lý do.
create or replace function st_approve(p_id uuid, p_decisions jsonb, p_reason text, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_perm('inventory.approve'); k stocktakes; e jsonb; l stocktake_lines; v_adj integer := 0; v_net numeric := 0;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  select * into k from stocktakes where id = p_id and shop_id = app_shop_id() for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if k.status <> 'submitted' then raise exception 'STOCKTAKE_LOCKED'; end if;
  if char_length(v_reason) < 3 then raise exception 'REASON_REQUIRED'; end if;
  update stocktake_lines set decision = 'keep' where stocktake_id = p_id;
  for e in select * from jsonb_array_elements(coalesce(p_decisions, '[]'::jsonb)) loop
    if coalesce(e->>'decision', '') not in ('adjust', 'keep') then raise exception 'DECISION_INVALID'; end if;
    select * into l from stocktake_lines where stocktake_id = p_id and ingredient_id = (e->>'ingredient_id')::uuid for update;
    if not found then raise exception 'NOT_FOUND'; end if;
    update stocktake_lines set decision = e->>'decision' where id = l.id;
    if e->>'decision' = 'adjust' and l.counted_qty <> l.system_qty then
      insert into stock_ledger (shift_id, ingredient_id, kind, qty_delta, ref_id, created_by, is_correction, note)
      values (null, l.ingredient_id, 'adjust', l.counted_qty - l.system_qty, p_id, v_me, true, v_reason);
      v_adj := v_adj + 1;
      v_net := v_net + (l.counted_qty - l.system_qty) * coalesce(l.unit_cost, 0);
    end if;
  end loop;
  update stocktakes set status = 'approved', reviewed_by = v_me, reviewed_at = now(),
         review_reason = v_reason, review_note = nullif(btrim(p_note), '') where id = p_id;
  perform _audit('st_approve', 'stocktake', p_id, jsonb_build_object('code', k.code, 'adjusted', v_adj, 'net_value', round(v_net)));
  return jsonb_build_object('id', p_id, 'code', k.code, 'adjusted_lines', v_adj, 'net_value', round(v_net)::bigint);
exception when invalid_text_representation then raise exception 'INPUT_INVALID';
end $$;

-- ======================================================================
-- 10) Hao hụt theo lô (HH) + yêu cầu sửa
-- ======================================================================
create or replace function inv_waste_add(p_ingredient uuid, p_qty integer, p_type text, p_note text default null, p_lot uuid default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_perm('inventory.record'); v_shift uuid := _open_shift_id(); v_shop uuid := app_shop_id();
  v_wt waste_types; v_id uuid; v_code text;
begin
  if p_qty is null or p_qty <= 0 or p_qty > 1000000000 then raise exception 'QTY_INVALID'; end if;
  select * into v_wt from waste_types where code = p_type and active and shop_id = v_shop;
  if not found then raise exception 'WASTE_TYPE_INVALID'; end if;
  if v_wt.requires_note and char_length(btrim(coalesce(p_note, ''))) < 5 then raise exception 'NOTE_REQUIRED'; end if;
  if not exists (select 1 from ingredients where id = p_ingredient and shop_id = v_shop and active) then raise exception 'NOT_FOUND'; end if;
  if p_lot is not null and not exists (select 1 from stock_lots where id = p_lot and ingredient_id = p_ingredient and shop_id = v_shop) then
    raise exception 'NOT_FOUND';
  end if;
  v_code := _inv_code('HH');
  insert into waste_logs (shift_id, ingredient_id, qty, reason_type, reason, entered_by, code, lot_id)
  values (v_shift, p_ingredient, p_qty, p_type, coalesce(nullif(btrim(p_note), ''), v_wt.label_vi), v_me, v_code, p_lot)
  returning id into v_id;
  insert into stock_ledger (shift_id, ingredient_id, kind, qty_delta, ref_id, created_by)
  values (v_shift, p_ingredient, 'waste', -p_qty, v_id, v_me);
  return jsonb_build_object('id', v_id, 'code', v_code, 'at', now());
end $$;

create or replace function inv_request_correction(p_kind text, p_ref uuid, p_note text) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_me uuid := _require_staff(); v_id uuid;
begin
  if p_kind not in ('waste', 'purchase') then raise exception 'KIND_INVALID'; end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'NOTE_REQUIRED'; end if;
  if p_kind = 'waste' and not exists (select 1 from waste_logs where id = p_ref and shop_id = app_shop_id() and entered_by = v_me) then
    raise exception 'NOT_FOUND';
  end if;
  if p_kind = 'purchase' and not exists (select 1 from purchase_orders where id = p_ref and shop_id = app_shop_id() and created_by = v_me) then
    raise exception 'NOT_FOUND';
  end if;
  insert into inventory_requests (kind, ref_id, note, created_by) values (p_kind, p_ref, btrim(p_note), v_me) returning id into v_id;
  return v_id;
end $$;

create or replace function inv_requests() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform _require_perm('inventory.costs');
  return coalesce((select jsonb_agg(jsonb_build_object(
            'id', r.id, 'kind', r.kind, 'ref_id', r.ref_id, 'note', r.note, 'created_at', r.created_at,
            'staff_name', (select s.full_name from staff s where s.id = r.created_by),
            'ref_code', case r.kind when 'waste' then (select w.code from waste_logs w where w.id = r.ref_id)
                                    else (select po.code from purchase_orders po where po.id = r.ref_id) end)
            order by r.created_at desc)
          from inventory_requests r where r.shop_id = app_shop_id() and r.status = 'open'), '[]'::jsonb);
end $$;

create or replace function inv_request_resolve(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform _require_owner();
  update inventory_requests set status = 'resolved', resolved_at = now() where id = p_id and shop_id = app_shop_id() and status = 'open';
  if not found then raise exception 'NOT_FOUND'; end if;
end $$;

-- Hao hụt bằng tiền (chủ): theo lý do, theo nguyên liệu, theo ngày; so với kỳ trước cùng độ dài
create or replace function inv_waste_overview(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; v_days integer; v_prev_from date; v_from_ts timestamptz; v_to_ts timestamptz;
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 366 then raise exception 'DATE_RANGE_INVALID'; end if;
  v_days := p_to - p_from + 1; v_prev_from := p_from - v_days;
  v_from_ts := (p_from::timestamp at time zone 'Asia/Ho_Chi_Minh');
  v_to_ts := ((p_to + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh');
  return (
    with w as (
      select w.id, w.code, w.ingredient_id, w.reason_type, w.qty, w.entered_at, i.name, i.unit, i.unit_cost,
             round(w.qty * coalesce(i.unit_cost, 0))::bigint as value
        from waste_logs w join ingredients i on i.id = w.ingredient_id
       where w.shop_id = v_shop and w.entered_at >= (v_prev_from::timestamp at time zone 'Asia/Ho_Chi_Minh') and w.entered_at < v_to_ts),
    cur as (select * from w where entered_at >= v_from_ts),
    prv as (select * from w where entered_at < v_from_ts)
    select jsonb_build_object(
      'from', p_from, 'to', p_to, 'updated_at', now(),
      'total_value', coalesce((select sum(value) from cur), 0),
      'prev_value', coalesce((select sum(value) from prv), 0),
      'entry_count', (select count(*) from cur),
      'unpriced_count', (select count(*) from cur where unit_cost is null),
      'by_reason', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'code', r.code, 'label', coalesce(t.label_vi, r.code), 'value', r.v, 'prev_value', r.pv, 'count', r.n) order by r.v desc)
          from (select c.reason_type as code, sum(c.value) as v, count(*) as n,
                       coalesce((select sum(p.value) from prv p where p.reason_type = c.reason_type), 0) as pv
                  from cur c group by c.reason_type) r
          left join waste_types t on t.shop_id = v_shop and t.code = r.code), '[]'::jsonb),
      'by_ingredient', coalesce((
        select jsonb_agg(jsonb_build_object('ingredient_id', g.ingredient_id, 'name', g.name, 'unit', g.unit,
                                            'qty', g.q, 'value', g.v) order by g.v desc, g.name)
          from (select c.ingredient_id, c.name, c.unit, sum(c.qty) as q, sum(c.value) as v from cur c
                 group by c.ingredient_id, c.name, c.unit) g), '[]'::jsonb),
      'daily', coalesce((
        select jsonb_agg(jsonb_build_object('date', d.day, 'value', coalesce(x.v, 0)) order by d.day)
          from (select p_from + g as day from generate_series(0, p_to - p_from) g) d
          left join (select _vn_day(c.entered_at) as day, sum(c.value) as v from cur c group by 1) x on x.day = d.day), '[]'::jsonb)));
end $$;

-- ======================================================================
-- 11) Tổng quan kho, tuần nhìn lại, đổi quán, trang chủ kho của nhân viên
-- ======================================================================
create or replace function _inv_shop_numbers(p_shop uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'stock_value', coalesce((select round(sum(greatest(s.stock, 0) * i.unit_cost))::bigint
                               from ingredients i join _inv_stock_all(p_shop) s on s.ingredient_id = i.id
                              where i.shop_id = p_shop and i.active and i.unit_cost is not null), 0),
    'waste_7d', coalesce((select round(sum(-l.qty_delta * coalesce(i.unit_cost, 0)))::bigint
                            from stock_ledger l join ingredients i on i.id = l.ingredient_id
                           where l.shop_id = p_shop and l.kind = 'waste' and l.at >= now() - interval '7 days'), 0))
$$;

create or replace function inv_overview() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; v_res jsonb; v_sug jsonb;
begin
  perform _require_perm('inventory.costs'); v_shop := app_shop_id();
  v_sug := po_suggestions();
  with st as (select * from _inv_stock_all(v_shop)),
       us as (select * from _inv_daily_use(v_shop, 7)),
  base as (
    select i.id, i.name, i.unit, i.group_name, i.unit_cost, i.min_stock_qty, greatest(st.stock, 0) as stock, st.stock as raw_stock,
           us.per_day, round(greatest(st.stock, 0) * i.unit_cost)::bigint as value
      from ingredients i join st on st.ingredient_id = i.id left join us on us.ingredient_id = i.id
     where i.shop_id = v_shop and i.active),
  lots as (select * from _inv_lots_all(v_shop) where qty_remaining > 0 and expiry_date is not null)
  select jsonb_build_object(
    'updated_at', now(),
    'stock_value', coalesce((select sum(value) from base where unit_cost is not null), 0),
    'unpriced_count', (select count(*) from base where unit_cost is null and stock > 0),
    'top_items', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'value', t.value) order by t.value desc)
                             from (select * from base where value > 0 order by value desc limit 3) t), '[]'::jsonb),
    'low_items', coalesce((select jsonb_agg(jsonb_build_object(
                    'id', b.id, 'name', b.name, 'unit', b.unit, 'stock', b.raw_stock,
                    'days_left', case when b.per_day > 0 then round(b.stock / b.per_day, 1) end,
                    'status', _inv_status(b.raw_stock, b.min_stock_qty))
                    order by (case when b.per_day > 0 then b.stock / b.per_day end) nulls last, b.name)
                    from base b where _inv_status(b.raw_stock, b.min_stock_qty) <> 'ok'
                      and (b.min_stock_qty > 0 or b.per_day > 0)), '[]'::jsonb),
    'expiring_lots', coalesce((select jsonb_agg(jsonb_build_object(
                    'ingredient_id', l.ingredient_id, 'name', (select n.name from base n where n.id = l.ingredient_id),
                    'code', l.code, 'expiry_date', l.expiry_date, 'qty_remaining', l.qty_remaining)
                    order by l.expiry_date)
                    from lots l where l.expiry_date <= _vn_day(now()) + 3), '[]'::jsonb),
    'pending_stocktakes', coalesce((select jsonb_agg(jsonb_build_object(
                    'id', k.id, 'code', k.code, 'submitted_at', k.submitted_at,
                    'staff_name', (select s.full_name from staff s where s.id = k.started_by),
                    'variance_lines', (select count(*) from stocktake_lines l where l.stocktake_id = k.id and l.counted_qty <> l.system_qty))
                    order by k.submitted_at)
                    from stocktakes k where k.shop_id = v_shop and k.status = 'submitted'), '[]'::jsonb),
    'needs_pricing_count', (select count(*) from purchase_orders where shop_id = v_shop and status = 'confirmed' and needs_pricing),
    'draft_order_count', (select count(*) from purchase_orders where shop_id = v_shop and status = 'draft'),
    'open_request_count', (select count(*) from inventory_requests where shop_id = v_shop and status = 'open'),
    'suggestion_count', jsonb_array_length(v_sug->'items'),
    'waste_7d', coalesce((select round(sum(-l.qty_delta * coalesce(i.unit_cost, 0)))::bigint
                            from stock_ledger l join ingredients i on i.id = l.ingredient_id
                           where l.shop_id = v_shop and l.kind = 'waste' and l.at >= now() - interval '7 days'), 0),
    'waste_prev_7d', coalesce((select round(sum(-l.qty_delta * coalesce(i.unit_cost, 0)))::bigint
                            from stock_ledger l join ingredients i on i.id = l.ingredient_id
                           where l.shop_id = v_shop and l.kind = 'waste'
                             and l.at >= now() - interval '14 days' and l.at < now() - interval '7 days'), 0),
    'ingredient_count', (select count(*) from base))
    into v_res;
  return v_res;
end $$;

create or replace function inv_week_review(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_shop uuid; v_days integer; v_from_ts timestamptz; v_to_ts timestamptz; v_stable integer := 0; v_total integer := 0; r record;
begin
  perform _require_owner(); v_shop := app_shop_id();
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then raise exception 'DATE_RANGE_INVALID'; end if;
  v_days := p_to - p_from + 1;
  v_from_ts := (p_from::timestamp at time zone 'Asia/Ho_Chi_Minh');
  v_to_ts := ((p_to + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh');
  -- một ngày "kho ổn" = mọi ca đóng trong ngày đó không có nguyên liệu lệch vàng/đỏ khi đối soát
  for r in
    select _vn_day(s.closed_at) as day,
           bool_and(not exists (select 1 from reconcile_shift(s.id) x where x.status in ('warn', 'alert'))) as ok
      from shifts s
     where s.shop_id = v_shop and s.status = 'closed' and s.closed_at >= v_from_ts and s.closed_at < v_to_ts
     group by 1
  loop
    v_total := v_total + 1;
    if r.ok then v_stable := v_stable + 1; end if;
  end loop;
  return jsonb_build_object(
    'from', p_from, 'to', p_to, 'days', v_days,
    'stock_value', (_inv_shop_numbers(v_shop)->>'stock_value')::bigint,
    'waste_value', coalesce((select round(sum(-l.qty_delta * coalesce(i.unit_cost, 0)))::bigint
                               from stock_ledger l join ingredients i on i.id = l.ingredient_id
                              where l.shop_id = v_shop and l.kind = 'waste' and l.at >= v_from_ts and l.at < v_to_ts), 0),
    'stable_days', v_stable, 'counted_days', v_total,
    'stocktakes_approved', (select count(*) from stocktakes where shop_id = v_shop and status = 'approved'
                              and reviewed_at >= v_from_ts and reviewed_at < v_to_ts),
    'orders_confirmed', (select count(*) from purchase_orders where shop_id = v_shop and status = 'confirmed'
                           and confirmed_at >= v_from_ts and confirmed_at < v_to_ts),
    'pending_stocktakes', (select count(*) from stocktakes where shop_id = v_shop and status = 'submitted'));
end $$;

-- Các quán mà người dùng là CHỦ: số liệu kho từng quán (dùng cho màn Đổi quán)
create or replace function inv_shops_snapshot() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_out jsonb := '[]'::jsonb; r record; v_n jsonb;
begin
  perform _require_owner();
  for r in
    select s.shop_id, sh.name, s.full_name, (s.shop_id = app_shop_id()) as is_current
      from staff s join shops sh on sh.id = s.shop_id
     where s.auth_user_id = auth.uid() and s.active and s.role = 'owner'
     order by s.created_at
  loop
    v_n := _inv_shop_numbers(r.shop_id);
    v_out := v_out || jsonb_build_object('shop_id', r.shop_id, 'shop_name', r.name, 'owner_name', r.full_name,
                                         'is_current', r.is_current, 'stock_value', v_n->'stock_value',
                                         'waste_7d', v_n->'waste_7d', 'updated_at', now());
  end loop;
  return v_out;
end $$;

-- Trang chủ Kho của nhân viên: việc cần làm, KHÔNG có số tồn/giá
create or replace function inv_staff_home() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_me uuid := _require_staff(); v_shop uuid := app_shop_id(); v_shift shifts; k stocktakes; v_hint jsonb;
begin
  select * into v_shift from shifts where shop_id = v_shop and status = 'open' limit 1;
  select * into k from stocktakes where shop_id = v_shop and started_by = v_me
   order by (status in ('draft', 'recount')) desc, coalesce(submitted_at, started_at) desc limit 1;
  select jsonb_build_object('ingredient_name', i.name, 'lot_code', l.code, 'expiry_date', l.expiry_date)
    into v_hint
    from _inv_lots_all(v_shop) l join ingredients i on i.id = l.ingredient_id
   where l.qty_remaining > 0 and l.expiry_date is not null and l.expiry_date <= _vn_day(now()) + 7
   order by l.expiry_date limit 1;
  return jsonb_build_object(
    'staff_name', (select full_name from staff where id = v_me),
    'shift_opened_at', v_shift.opened_at,
    'shift_open', v_shift.id is not null,
    'stocktake', case when k.id is null then null else jsonb_build_object(
        'id', k.id, 'code', k.code, 'status', k.status, 'saved_at', k.saved_at, 'submitted_at', k.submitted_at,
        'counted', (select count(*) from stocktake_lines l where l.stocktake_id = k.id and l.counted_qty is not null),
        'total', (select count(*) from stocktake_lines l where l.stocktake_id = k.id),
        'review_note', case when k.status = 'recount' then k.review_note end) end,
    'hint', v_hint);
end $$;

